using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;

// Dungeon Run data (docs/design/dungeon-run.md): rules, classes, treasures, bosses, unlocks and the version-1 save map
// (run-v1.json, schema 2), the card pool (pool-v1.json, schema 2: starter decks, bundles, band-1/2 boss decks) and the
// shared draft catalog (catalog-v1.json, generated by tools/dungeon-run-catalog: the pool's bundles plus the original
// adventure buckets). Pure data, no engine or client types.

internal sealed class DungeonRunRules
{
    internal int Floors = 8;
    internal int[] BandSplit = { 3, 3, 1 };
    internal int FinalFloor = 8;
    internal int[] BandHealth = { 30, 40, 50 };
    internal int FinalHealth = 60;
    internal int StarterSize = 10;
    internal int[] TreasureFloors = { 1, 3, 5 };
    internal int ReofferAfterFloors = 2;
    internal int PityWindow = 2;
    internal int UpgradeEveryFloors = 2;
    /// <summary>Starter decks per class (design R4).</summary>
    internal int DeckOptions = 3;
    /// <summary>Hero powers per class: the basic power first.</summary>
    internal int PowerOptions = 3;
    /// <summary>
    /// A catalog run takes one pool entry (an original bucket) at most this many times (run-v1.json "draft.bucketMaxTakes",
    /// default 3); a fixed entry is taken at most once.
    /// </summary>
    internal int BucketMaxTakes = 3;
    /// <summary>Offer weight multiplier of a catalog entry whose classesAll pair the run has (a Tombs bucket for its explorer; "draft.dualMatchWeight").</summary>
    internal int DualMatchWeight = 2;

    /// <summary>Band (1-3) of a non-final floor, from <see cref="BandSplit"/>.</summary>
    internal int BandOf(int floor)
    {
        int end = 0;
        for (int b = 0; b < BandSplit.Length; b++)
        {
            end += BandSplit[b];
            if (floor <= end) return b + 1;
        }
        return BandSplit.Length;
    }

    /// <summary>Shrine tier: 1 on band 1, 2 on band 2, 3 on band 3 and the final floor.</summary>
    internal int ShrineTier(int floor) => floor >= FinalFloor ? 3 : BandOf(floor);
}

/// <summary>A selectable class (design R2): its portrait, its powers (the basic one first) and its starter decks (the default first).</summary>
internal sealed class DungeonRunClass
{
    /// <summary>The engine CardClass name ("MAGE").</summary>
    internal string Id, Name, HeroCard;
    /// <summary>Hero power card ids or content keys; the first is the class basic power and needs no unlock.</summary>
    internal List<string> Powers = new List<string>();
    /// <summary>Unlock key per power that needs one.</summary>
    internal Dictionary<string, string> PowerUnlocks = new Dictionary<string, string>();
    /// <summary>Starter deck ids; the first is the default and needs no unlock.</summary>
    internal List<string> Decks = new List<string>();
    /// <summary>
    /// The run's classes (run-v1.json "classes"; absent = <c>[Id]</c>). A dual-class row (Tombs of Terror) has two, with
    /// <see cref="Id"/> "A_B"; <c>Classes[0]</c> is the primary class: the portrait's class and the engine's generation class.
    /// </summary>
    internal List<string> Classes = new List<string>();
    /// <summary>
    /// False for a row that ships disabled (run-v1.json "enabled": false; a dual row with no valid starter deck): it is kept
    /// in <see cref="DungeonRunData.DisabledClasses"/>, never in <see cref="DungeonRunData.Classes"/>, so no run starts on it.
    /// </summary>
    internal bool Enabled = true;
    /// <summary>Why a disabled row is disabled (run-v1.json "disabledReason").</summary>
    internal string DisabledReason;
    /// <summary>A dual-class row (Tombs of Terror explorer).</summary>
    internal bool IsDual => ClassSet.Count == 2;

    // ---- phase 6: named adventure heroes (run-v1.json "heroRows"; the dual rows of "catalogClasses" are hero rows too)
    internal const string KindClass = "class", KindHero = "hero";
    /// <summary>The adventures a hero row may name (<see cref="Adventure"/>): picker grouping and treasure-pool scope.</summary>
    internal static readonly string[] Adventures = { "DungeonRun", "MonsterHunt", "Heist", "Tombs", "Rumble" };
    /// <summary>"class" (default: one of the eleven class rows) or "hero" (a named adventure hero, <see cref="IsHero"/>).</summary>
    internal string Kind = KindClass;
    /// <summary>A hero row's adventure (<see cref="Adventures"/>), or null for a class row.</summary>
    internal string Adventure;
    /// <summary>The run hero's base Health; 0 keeps the portrait's printed Health (every named hero row sets 30, an adaptation).</summary>
    internal int Health;
    /// <summary>The signature treasures a run of this row picks one of at start (Tombs of Terror loadouts); empty for none.</summary>
    internal List<string> Signatures = new List<string>();
    /// <summary>How many of the unlocked <see cref="Signatures"/> are offered at start (the original Tombs pick of 3).</summary>
    internal int SignatureOffer = 3;
    /// <summary>Treasure-tag vocabulary this row adds to the affinity weighting of its treasure drafts.</summary>
    internal List<string> TreasureTags = new List<string>();
    /// <summary>A named adventure hero row (Kind "hero"): it sits beside its primary class's row in the picker.</summary>
    internal bool IsHero => Kind == KindHero;

    /// <summary><see cref="Classes"/>, or <c>[Id]</c> for a row that lists none.</summary>
    internal IReadOnlyList<string> ClassSet => Classes.Count > 0 ? Classes : Id == null ? new string[0] : new[] { Id };
    internal string DefaultPower => Powers.FirstOrDefault();
    internal string DefaultDeck => Decks.FirstOrDefault();
    internal string PowerUnlock(string power) => power != null && PowerUnlocks.TryGetValue(power, out string key) ? key : null;
}

/// <summary>A themed starter deck (pool-v1.json "starterDecks").</summary>
internal sealed class DungeonRunStarterDeck
{
    internal string Id, Class, Name, Description, Unlock;
    /// <summary>
    /// Phase 7: the Rumble Run board shrine this starter belongs to (run-v1.json catalog deck "shrine", "TRLA_&lt;n&gt;"); null for
    /// every other deck. A new run on it starts with that shrine on the board when the engine scripts it (DungeonRun.NewRun).
    /// </summary>
    internal string Shrine;
    /// <summary>Treasure-tag vocabulary added to the class tags for treasure affinity (design F6).</summary>
    internal List<string> TreasureTags = new List<string>();
    internal List<string> Cards = new List<string>();
    /// <summary>
    /// A generated starter (phase 6, the Heist and Tombs "Random" decks): <see cref="GeneratorRandomClass"/> or
    /// <see cref="GeneratorRandomDual"/>; null for a fixed deck. A generated deck lists no <see cref="Cards"/>: NewRun draws
    /// <see cref="DungeonRunRules.StarterSize"/> admitted catalog cards of the row's classes from the run seed
    /// (DungeonRun.GenerateStarter); the display card (<see cref="DisplayCard"/>, DALA_80x or ULDA_90x) never enters a match.
    /// </summary>
    internal string Generator;
    /// <summary>The client card a generated deck shows on its plank (never a match card); null for a fixed deck.</summary>
    internal string DisplayCard;
    internal const string GeneratorRandomClass = "random-class", GeneratorRandomDual = "random-dual";
    internal bool IsGenerated => Generator != null;
}

/// <summary>Which runs may be offered a treasure: any listed class, starter deck or power. Empty = every run.</summary>
internal sealed class DungeonRunScope
{
    internal List<string> Classes = new List<string>(), Decks = new List<string>(), Powers = new List<string>();
    internal bool IsEmpty => Classes.Count == 0 && Decks.Count == 0 && Powers.Count == 0;
    internal bool Matches(string cls, string deck, string power) =>
        IsEmpty || (cls != null && Classes.Contains(cls)) || (deck != null && Decks.Contains(deck)) || (power != null && Powers.Contains(power));
    /// <summary>A run of classes <paramref name="classes"/> (a dual-class row's two): a class scope matches when any run class matches.</summary>
    internal bool Matches(IReadOnlyList<string> classes, string deck, string power) =>
        IsEmpty || (classes != null && classes.Any(Classes.Contains)) || (deck != null && Decks.Contains(deck)) || (power != null && Powers.Contains(power));
}

/// <summary>
/// How a version-1 hero id maps onto the class model (save migration). <see cref="Power"/> repairs a version-1 run that
/// lost its power. A version-1 run keeps the deck it has: none of the version-1 starters is a version-2 starter deck.
/// </summary>
internal sealed class DungeonRunLegacyHero
{
    internal string Class, Power;
}

internal sealed class DungeonRunTreasure
{
    internal string Id, Rarity, UpgradesTo;
    internal bool Universal, Active, Offered = true;
    /// <summary>Kept only so version-1 saves that hold it still resolve; never offered.</summary>
    internal bool Legacy;
    internal List<string> Tags = new List<string>();
    internal DungeonRunScope Scope = new DungeonRunScope();

    // ---- phase 6: signature loadouts and evolving artifacts
    /// <summary>A signature treasure: offered only through its hero row's loadout (<see cref="DungeonRunClass.Signatures"/>), never in a draft.</summary>
    internal bool Signature;
    /// <summary>The unlock key a signature needs before its row offers it; null for none.</summary>
    internal string Unlock;
    /// <summary>
    /// A profile-level upgrade (Jr. to Sr., design section 4 kind C): when this unlock holds at NewRun, the run starts with
    /// <see cref="UpgradesTo"/> instead. Such a treasure never upgrades during a run.
    /// </summary>
    internal string UpgradeUnlock;
    /// <summary>When a run upgrade fires: <see cref="UpgradeOnFloors"/> (default: every rules.upgradeEveryFloors floors),
    /// <see cref="UpgradeOnActClear"/> (an act's major beaten) or "bossWins:N" (N won fights).</summary>
    internal string UpgradeOn = UpgradeOnFloors;
    /// <summary>What the upgrade swaps: <see cref="SlotDeck"/> (the treasure's card record), <see cref="SlotPower"/> (the run's
    /// hero power) or <see cref="SlotPassive"/> (a passive treasure).</summary>
    internal string UpgradeSlot = SlotDeck;
    /// <summary>The adventure tag the treasure-Discover helper filters on (RunContext.TreasurePool); null for any.</summary>
    internal string Pool;
    /// <summary>
    /// Which runs offer it (run-v1.json "runs"): <see cref="RunsAll"/> (default), <see cref="RunsAct"/> (an act run only: the
    /// phase-6 adventure treasures, so a legacy run's offers stay as released) or <see cref="RunsLegacy"/> (a legacy run only:
    /// a SoloStone treasure an original replaces on act runs, spare_crystal by LOOTA_801). A save that holds it still resolves.
    /// </summary>
    internal string Runs = RunsAll;
    internal const string RunsAll = "all", RunsAct = "act", RunsLegacy = "legacy";
    /// <summary><see cref="Runs"/> lets an act run (<paramref name="actRun"/>) or a legacy run offer it.</summary>
    internal bool OfferedOn(bool actRun) => Runs == RunsAll || Runs == RunsAct && actRun || Runs == RunsLegacy && !actRun;
    internal const string UpgradeOnFloors = "floors", UpgradeOnActClear = "actClear", UpgradeOnBossWins = "bossWins";
    internal const string SlotDeck = "deck", SlotPower = "power", SlotPassive = "passive";

    /// <summary>The N of "bossWins:N", or 0 when <see cref="UpgradeOn"/> is not a boss-win count (or is malformed).</summary>
    internal int BossWins => BossWinsOf(UpgradeOn);
    /// <summary><see cref="UpgradeOn"/> is one of the known triggers.</summary>
    internal bool UpgradeOnKnown => KnownTrigger(UpgradeOn);

    internal static int BossWinsOf(string on) => on != null && on.StartsWith(UpgradeOnBossWins + ":", StringComparison.Ordinal)
        && int.TryParse(on.Substring(UpgradeOnBossWins.Length + 1), System.Globalization.NumberStyles.None, System.Globalization.CultureInfo.InvariantCulture, out int n) ? n : 0;
    internal static bool KnownTrigger(string on) => on == UpgradeOnFloors || on == UpgradeOnActClear || BossWinsOf(on) > 0;
}

/// <summary>A run-persistent hero power upgrade (run-v1.json "powerUpgrades"): the run's power <see cref="From"/> becomes <see cref="To"/>.</summary>
internal sealed class DungeonRunPowerUpgrade
{
    internal string From, To;
    /// <summary>When it fires (the vocabulary of <see cref="DungeonRunTreasure.UpgradeOn"/>).</summary>
    internal string On = DungeonRunTreasure.UpgradeOnActClear;
}

internal sealed class DungeonRunBoss
{
    internal string Id, Name, HeroCard, Power, Deck, Unlock;
    /// <summary>AI archetype for the boss plan (aggro/tempo/midrange/control). Library decks fall back to their own tag.</summary>
    internal string Archetype;
    internal int Band;
    internal int? Health;
    internal bool Final, Challenge;
    /// <summary>
    /// The encounter pools the boss is drawn from on an act schedule (run-v1.json "pools"; absent = <c>["band&lt;n&gt;"]</c>,
    /// or <c>["final"]</c> for a final boss). Pool "leftover" is computed, never listed.
    /// </summary>
    internal List<string> Pools = new List<string>();
    /// <summary>Where the encounter comes from ("solostone"; phase 8 adds LOOT, GIL, TRL, DALA and ULDA).</summary>
    internal string Provenance = "solostone";
    /// <summary>The encounter family (a phase-8 hook for twists and anomalies), or null.</summary>
    internal string Family;
    /// <summary>On an act run, the boss's own <see cref="Health"/> replaces the act's health curve (health that is part of its identity).</summary>
    internal bool FixedHealth;
    /// <summary>The most start-mana bonus an act run gives this boss (null: <see cref="DungeonRunSchedules.DefaultBossManaCap"/>).</summary>
    internal int? BossManaCap;
    /// <summary>Schedule modifier ids never active on this boss's act (the act's modifier offer leaves them out).</summary>
    internal List<string> IncompatibleModifiers = new List<string>();

    // ---- phase 8: imported encounters (encounters-v1.json; DungeonRunEncounterData.Parse). All empty on a custom boss.
    /// <summary>An imported adventure encounter (any provenance but "solostone").</summary>
    internal bool IsEncounter => Provenance != DungeonRunEncounterData.CustomProvenance;
    /// <summary>The encounter's tier ("1".."4", "major1".."major3", "finale"): its pool is DungeonRunEncounterData.PoolOf(Tier). Null on a custom boss.</summary>
    internal string Tier;
    /// <summary>An encounter's explicit Health offset over the act curve (a custom boss derives it from its band: DungeonRun.HealthOffset).</summary>
    internal int HealthOffset;
    /// <summary>Where the row's level comes from ("printed-health", "wiki-level-table", "rumble-round") and its original value.</summary>
    internal string LevelSource;
    internal int LevelOriginal;
    /// <summary>The closed flag vocabulary (DungeonRunEncounterData.Flags): rule incompatibility and tests read it.</summary>
    internal List<string> Flags = new List<string>();
    /// <summary>The boss's generation may yield Secrets (RunMatchPlan.BossGeneratedSecrets); the validator checks its yield pool.</summary>
    internal bool BossGeneratedSecrets;
    /// <summary>The start block, or null.</summary>
    internal DungeonRunStart Start;
    /// <summary>The forms after the row's own (form 0 is HeroCard and Power), in order.</summary>
    internal List<DungeonRunForm> Forms = new List<DungeonRunForm>();
    /// <summary>Shrine variants (a Rumble Run champion): one is drawn per fight from the run seed.</summary>
    internal List<DungeonRunVariant> Variants = new List<DungeonRunVariant>();
    /// <summary>Hero cards the run player is given for this fight (Hagatha).</summary>
    internal List<DungeonRunHeroCard> HeroCards = new List<DungeonRunHeroCard>();
    /// <summary>The run player's relay heroes (a finale row with flag "relay").</summary>
    internal List<DungeonRunRelayHero> Relay = new List<DungeonRunRelayHero>();
    /// <summary>Boss-only cards the power or deck creates (tokens), for the client checks and the ledger.</summary>
    internal List<string> Cards = new List<string>();
    /// <summary>Global rule ids never active while this boss is in the act (the anomaly offer and the twist roll leave them out).</summary>
    internal List<string> IncompatibleRules = new List<string>();
    /// <summary>Where the deck comes from and what the encounter tool changed in it; null on a custom boss.</summary>
    internal DungeonRunDeckSource Source;
    internal bool HasFlag(string flag) => Flags.Contains(flag);
}

/// <summary>One card a pool entry can draw (catalog-v1.json "members").</summary>
internal sealed class DungeonRunCandidate
{
    /// <summary>The engine id drawn; <see cref="WikiId"/> is the id the source listed (a reprint id resolves to its original).</summary>
    internal string Id, WikiId;
    internal int Weight = 1;
    /// <summary>Off-class but legal inside this entry only (Monster Hunt Shaw and Tess buckets).</summary>
    internal bool Grant;
}

/// <summary>Where a catalog entry comes from (an original adventure bucket, or a SoloStone bundle).</summary>
internal sealed class DungeonRunProvenance
{
    internal string Adventure, Hero, Label, LabelCardId, Membership, Source;
}

/// <summary>A quest card in a pool entry. Recorded only: auto-offering it on the first take is a later phase.</summary>
internal sealed class DungeonRunQuest
{
    internal string CardId;
    internal bool OnFirstTake;
}

/// <summary>
/// A draftable catalog entry. A "fixed" entry offers exactly its three <see cref="Cards"/> (the 52 SoloStone bundles of
/// pool-v1.json, <see cref="Legacy"/>); a "pool" entry is an original bucket whose three cards are drawn from
/// <see cref="Candidates"/>. An entry built with an object initializer is a fixed legacy bundle (the defaults).
/// </summary>
internal sealed class DungeonRunBundle
{
    /// <summary><see cref="Class"/> is <c>Classes[0]</c> ("NEUTRAL" for a neutral entry); <see cref="Theme"/> is <c>Themes[0]</c>.</summary>
    internal string Id, Class, Theme;
    internal List<string> Cards = new List<string>();
    /// <summary>"fixed" or "pool".</summary>
    internal string Kind = KindFixed;
    internal const string KindFixed = "fixed", KindPool = "pool";
    internal bool Legacy = true;
    internal List<string> Classes = new List<string>();
    /// <summary>Classes the run must all have (a Tombs of Terror pair); empty for none.</summary>
    internal List<string> ClassesAll = new List<string>();
    /// <summary>A mechanic the run must support ("secret"), or null.</summary>
    internal string RequiresMechanic;
    internal List<DungeonRunCandidate> Candidates = new List<DungeonRunCandidate>();
    /// <summary>Highlander: a drawn card leaves the list for that offer.</summary>
    internal bool Distinct;
    internal List<string> Themes = new List<string>();
    internal string Label, LabelKey, Withdrawn;
    internal int Weight = 1;
    internal double AvgCost;
    internal bool Offerable = true;
    internal List<DungeonRunProvenance> Provenance = new List<DungeonRunProvenance>();
    internal DungeonRunQuest Quest;

    internal bool IsPool => Kind == KindPool;
    internal bool IsNeutral => ClassSet.Count == 1 && ClassSet[0] == "NEUTRAL";
    /// <summary>The entry's classes: <see cref="Classes"/>, or <c>[Class]</c> for an initializer-built bundle.</summary>
    internal IReadOnlyList<string> ClassSet => Classes.Count > 0 ? Classes : new[] { Class ?? "NEUTRAL" };
    internal string PrimaryTheme => Themes.Count > 0 ? Themes[0] : Theme;

    /// <summary>A run of class <paramref name="classId"/> can be offered this bundle: it is neutral or the class's own (legacy runs).</summary>
    internal bool OfferedTo(string classId) => Class == "NEUTRAL" || Class == classId;

    /// <summary>
    /// A catalog run of classes <paramref name="runClasses"/> can be offered this entry: it is offerable; neutral or one of
    /// its classes is a run class; every <see cref="ClassesAll"/> class is a run class; and <see cref="RequiresMechanic"/>
    /// holds (<paramref name="mechanicHolds"/>, DungeonRunAdmission.MechanicHolds; null means no mechanic holds).
    /// </summary>
    internal bool EligibleFor(IReadOnlyList<string> runClasses, Func<string, bool> mechanicHolds)
    {
        if (!Offerable || runClasses == null) return false;
        if (!IsNeutral && !ClassSet.Any(runClasses.Contains)) return false;
        if (ClassesAll.Any(c => !runClasses.Contains(c))) return false;
        return RequiresMechanic == null || mechanicHolds != null && mechanicHolds(RequiresMechanic);
    }
}

/// <summary>An unlock condition: all set fields must hold (allOf/anyOf combine sub-conditions).</summary>
internal sealed class DungeonRunCondition
{
    internal int? FloorReached, RunsWon;
    /// <summary>Distinct classes with at least one random-seed win.</summary>
    internal int? ClassesWon;
    /// <summary>Act majors beaten by random-seed act runs (DungeonRunHeroStats.MajorsCleared; legacy runs never add to it).</summary>
    internal int? MajorsCleared;
    /// <summary>Scopes floorReached/runsWon to one class's stats; null = all classes.</summary>
    internal string Class;
    internal List<DungeonRunCondition> AllOf, AnyOf;
}

internal sealed class DungeonRunData
{
    internal string DataVersion;
    /// <summary>
    /// The client check the loaded catalog was filtered with (DungeonRunValidator.DropClientUnknown); null headless. A catalog
    /// pick rechecks its stored cards with it, so a card the client no longer knows is refused, never drafted.
    /// </summary>
    internal Func<string, bool> ClientKnows;
    internal DungeonRunRules Rules = new DungeonRunRules();
    internal List<DungeonRunClass> Classes = new List<DungeonRunClass>();
    /// <summary>
    /// Catalog class rows that ship disabled (run-v1.json "catalogClasses" with "enabled": false), with their starter decks in
    /// <see cref="DisabledDecks"/>: never offered, never validated as playable, read by the restoration ledger.
    /// </summary>
    internal List<DungeonRunClass> DisabledClasses = new List<DungeonRunClass>();
    internal List<DungeonRunStarterDeck> DisabledDecks = new List<DungeonRunStarterDeck>();
    internal List<DungeonRunTreasure> Treasures = new List<DungeonRunTreasure>();
    /// <summary>Run-persistent hero power upgrades (run-v1.json "powerUpgrades"), by the power they upgrade.</summary>
    internal Dictionary<string, DungeonRunPowerUpgrade> PowerUpgrades = new Dictionary<string, DungeonRunPowerUpgrade>(StringComparer.Ordinal);
    internal Dictionary<string, List<string>> ClassTags = new Dictionary<string, List<string>>();
    internal List<DungeonRunBoss> Bosses = new List<DungeonRunBoss>();
    internal Dictionary<string, DungeonRunCondition> Unlocks = new Dictionary<string, DungeonRunCondition>();
    internal List<DungeonRunStarterDeck> Decks = new List<DungeonRunStarterDeck>();
    /// <summary>Version-1 hero id -> class (and the deck/power its runs keep), for save migration.</summary>
    internal Dictionary<string, DungeonRunLegacyHero> LegacyHeroes = new Dictionary<string, DungeonRunLegacyHero>();
    /// <summary>Version-1 unlock key -> the class unlock keys that keep what it gave.</summary>
    internal Dictionary<string, List<string>> LegacyUnlocks = new Dictionary<string, List<string>>();
    /// <summary>
    /// Every draftable entry. Without a catalog: the pool-v1.json bundles. With catalog-v1.json: its entries, the 52 fixed
    /// legacy bundles first in pool order, then the pool entries in ordinal id order.
    /// </summary>
    internal List<DungeonRunBundle> Bundles = new List<DungeonRunBundle>();
    /// <summary>The legacy fixed bundles (pool-v1.json, in pool order): what a legacy run (CatalogVersion 0) is offered.</summary>
    internal IEnumerable<DungeonRunBundle> LegacyBundles => Bundles.Where(b => b.Legacy);
    /// <summary>catalog-v1.json "catalogVersion"; 0 when no catalog was loaded.</summary>
    internal int CatalogVersion;
    /// <summary>Boss decks by id: the pool's band-1/2 decks plus NPC library decks the bosses name.</summary>
    internal Dictionary<string, List<string>> BossDecks = new Dictionary<string, List<string>>();
    /// <summary>Deckbuilding selections of library boss decks, by deck id then owner card id.</summary>
    internal Dictionary<string, Dictionary<string, string[]>> BossSideboards = new Dictionary<string, Dictionary<string, string[]>>();
    /// <summary>
    /// The act/floor schedules (schedule-v1.json), or null when none was loaded: then every new run is a legacy run on the
    /// fixed eight floors of <see cref="Rules"/>, as every run of a save before version 4 is.
    /// </summary>
    internal DungeonRunSchedules Schedules;
    /// <summary>
    /// Phase 7: the Rumble Run teammates by class (run-v1.json "teammates", class name to six TRLA ids, 54 in all, the nine
    /// start-of-game companions included). The teammate draft offers a run's class row the scripted, admitted ones it has not
    /// taken (DungeonRun.TeammatePool). Empty when the data has no table.
    /// </summary>
    internal Dictionary<string, List<string>> Teammates = new Dictionary<string, List<string>>(StringComparer.Ordinal);
    /// <summary>Phase 7: the nine Rumble Run shrine upgrades (run-v1.json "shrineUpgrades", TRLA_801..809), in table order.</summary>
    internal List<string> ShrineUpgrades = new List<string>();
    /// <summary>Bob's tavern table (tavern-v1.json), or null when none was loaded: then a tavern node opens with no offers.</summary>
    internal DungeonRunTavernTable Tavern;
    /// <summary>encounters-v1.json "encountersVersion"; 0 when no encounter file was loaded (then <see cref="Bosses"/> holds the custom bosses only).</summary>
    internal int EncountersVersion;
    /// <summary>The imported encounters (phase 8): the rows of <see cref="Bosses"/> with a provenance other than "solostone", in file order.</summary>
    internal IEnumerable<DungeonRunBoss> Encounters => Bosses.Where(b => b.IsEncounter);
    /// <summary>The custom SoloStone bosses (run-v1.json "bosses"), in data order.</summary>
    internal IEnumerable<DungeonRunBoss> CustomBosses => Bosses.Where(b => !b.IsEncounter);
    /// <summary>Encounters the file lists as not imported, with the reason (the ledger's rejected-with-reason rows).</summary>
    internal List<DungeonRunRejectedEncounter> RejectedEncounters = new List<DungeonRunRejectedEncounter>();

    internal DungeonRunClass Class(string id) => FindClass(id) ?? throw new KeyNotFoundException("Dungeon Run class " + id);
    internal DungeonRunClass FindClass(string id) => id == null ? null : Classes.FirstOrDefault(c => c.Id == id);
    internal DungeonRunStarterDeck Deck(string id) => FindDeck(id) ?? throw new KeyNotFoundException("Dungeon Run deck " + id);
    internal DungeonRunStarterDeck FindDeck(string id) => id == null ? null : Decks.FirstOrDefault(d => d.Id == id);
    internal DungeonRunBoss Boss(string id) => Bosses.FirstOrDefault(b => b.Id == id) ?? throw new KeyNotFoundException("Dungeon Run boss " + id);
    internal DungeonRunTreasure Treasure(string id) => FindTreasure(id) ?? throw new KeyNotFoundException("Dungeon Run treasure " + id);
    internal DungeonRunTreasure FindTreasure(string id) => id == null ? null : Treasures.FirstOrDefault(t => t.Id == id);
    /// <summary>The class rows (Kind "class": the eleven classes), in data order: the picker's first step.</summary>
    internal IEnumerable<DungeonRunClass> ClassRows => Classes.Where(c => !c.IsHero);
    /// <summary>The playable named hero rows (Kind "hero"), in data order.</summary>
    internal IEnumerable<DungeonRunClass> HeroRows => Classes.Where(c => c.IsHero);
    /// <summary>
    /// The treasure-affinity tags of a row: its own classTags entry, else (a hero row) its primary class's; plus the row's own
    /// treasureTags. Empty for a null row.
    /// </summary>
    internal List<string> TagsOf(DungeonRunClass cls)
    {
        if (cls == null) return new List<string>();
        var tags = new List<string>(ClassTags.TryGetValue(cls.Id, out var own) ? own
            : cls.ClassSet.Count > 0 && ClassTags.TryGetValue(cls.ClassSet[0], out var primary) ? primary : new List<string>());
        foreach (string t in cls.TreasureTags) if (!tags.Contains(t)) tags.Add(t);
        return tags;
    }

    /// <summary>
    /// Parses the two data files. <paramref name="npcDecksJson"/> is data/npc/decks-v1.json; only the decks a
    /// boss names are read from it.
    /// </summary>
    internal static DungeonRunData Parse(string runJson, string poolJson, string npcDecksJson) => Parse(runJson, poolJson, npcDecksJson, null);

    /// <summary>
    /// Parses the data files and, when <paramref name="catalogJson"/> is given (data/dungeon-run/catalog-v1.json), builds
    /// <see cref="Bundles"/> from the catalog. The catalog must carry exactly the pool's bundles: its poolBundlesHash and
    /// its fixed entries must both hash to <see cref="PoolBundlesHash"/> of pool-v1.json, else it is stale.
    /// </summary>
    internal static DungeonRunData Parse(string runJson, string poolJson, string npcDecksJson, string catalogJson) =>
        Parse(runJson, poolJson, npcDecksJson, catalogJson, null);

    /// <summary>
    /// As above, and when <paramref name="scheduleJson"/> is given (data/dungeon-run/schedule-v1.json) loads the act/floor
    /// schedules, so a new run follows the default schedule (DungeonRun.NewRun).
    /// </summary>
    internal static DungeonRunData Parse(string runJson, string poolJson, string npcDecksJson, string catalogJson, string scheduleJson) =>
        Parse(runJson, poolJson, npcDecksJson, catalogJson, scheduleJson, null);

    /// <summary>As above, and when <paramref name="tavernJson"/> is given (data/dungeon-run/tavern-v1.json) loads Bob's tavern table.</summary>
    internal static DungeonRunData Parse(string runJson, string poolJson, string npcDecksJson, string catalogJson, string scheduleJson, string tavernJson) =>
        Parse(runJson, poolJson, npcDecksJson, catalogJson, scheduleJson, tavernJson, null);

    /// <summary>
    /// As above, and when <paramref name="encountersJson"/> is given (data/dungeon-run/encounters-v1.json, phase 8) appends the
    /// imported encounters after the custom bosses and their decks to the boss decks. Without it the data is exactly what it
    /// was before phase 8 (every earlier harness loads it so).
    /// </summary>
    internal static DungeonRunData Parse(string runJson, string poolJson, string npcDecksJson, string catalogJson, string scheduleJson, string tavernJson,
        string encountersJson)
    {
        var data = ParseData(runJson, poolJson, npcDecksJson, catalogJson);
        if (scheduleJson != null) data.Schedules = DungeonRunSchedules.Parse(scheduleJson);
        if (tavernJson != null) data.Tavern = DungeonRunTavernTable.Parse(tavernJson);
        if (encountersJson != null) DungeonRunEncounterData.Parse(data, encountersJson);
        return data;
    }

    private static DungeonRunData ParseData(string runJson, string poolJson, string npcDecksJson, string catalogJson)
    {
        var data = new DungeonRunData();
        var run = Obj(NpcWorldJson.Parse(runJson));
        if (NpcWorldJson.Integer(run, "schemaVersion") != SchemaVersion) throw new InvalidDataException("run-v1.json: unsupported schemaVersion");
        data.DataVersion = NpcWorldJson.Text(run, "dataVersion");

        var rules = Obj(run["rules"]);
        var r = data.Rules;
        r.Floors = NpcWorldJson.Integer(rules, "floors");
        r.BandSplit = Ints(rules, "bandSplit");
        r.FinalFloor = NpcWorldJson.Integer(rules, "finalFloor");
        r.BandHealth = Ints(rules, "bandHealth");
        r.FinalHealth = NpcWorldJson.Integer(rules, "finalHealth");
        r.StarterSize = NpcWorldJson.Integer(rules, "starterSize");
        r.TreasureFloors = Ints(rules, "treasureFloors");
        r.ReofferAfterFloors = NpcWorldJson.Integer(rules, "reofferAfterFloors");
        r.PityWindow = NpcWorldJson.Integer(rules, "pityWindow");
        r.UpgradeEveryFloors = NpcWorldJson.Integer(rules, "upgradeEveryFloors");
        r.DeckOptions = NpcWorldJson.Integer(rules, "deckOptions");
        r.PowerOptions = NpcWorldJson.Integer(rules, "powerOptions");
        if (run.TryGetValue("draft", out object draftValue) && draftValue is IDictionary<string, object> draft)
        {
            r.BucketMaxTakes = NpcWorldJson.Integer(draft, "bucketMaxTakes", r.BucketMaxTakes);
            r.DualMatchWeight = NpcWorldJson.Integer(draft, "dualMatchWeight", r.DualMatchWeight);
        }

        DungeonRunClass ClassRow(IDictionary<string, object> row) => new DungeonRunClass
        {
            Id = NpcWorldJson.Text(row, "id"),
            Name = NpcWorldJson.Text(row, "name"),
            HeroCard = NpcWorldJson.Text(row, "hero"),
            Powers = NpcWorldJson.Strings(row, "powers", true),
            PowerUnlocks = StringMap(row, "powerUnlocks"),
            Decks = NpcWorldJson.Strings(row, "decks", true),
            Classes = NpcWorldJson.Strings(row, "classes") ?? new List<string>(),
            Enabled = NpcWorldJson.Boolean(row, "enabled", true),
            DisabledReason = NpcWorldJson.Text(row, "disabledReason", false),
            Kind = NpcWorldJson.Text(row, "kind", false) ?? DungeonRunClass.KindClass,
            Adventure = NpcWorldJson.Text(row, "adventure", false),
            Health = NpcWorldJson.Integer(row, "health", 0),
            Signatures = NpcWorldJson.Strings(row, "signatures") ?? new List<string>(),
            SignatureOffer = NpcWorldJson.Integer(row, "signatureOffer", 3),
            TreasureTags = NpcWorldJson.Strings(row, "treasureTags") ?? new List<string>(),
        };
        foreach (var row in NpcWorldJson.List(run, "classes").Cast<object>().Select(Obj))
        {
            var cls = ClassRow(row);
            if (!cls.Enabled) throw new InvalidDataException("run-v1.json: class " + cls.Id + " is disabled; only a catalog class row may be");
            data.Classes.Add(cls);
        }
        // Catalog class rows (the dual-class explorers) are a catalog run's only, so they load with the catalog: legacy runs
        // are single-class by definition, and data without a catalog is the legacy mode. A disabled row is kept aside.
        var catalogTags = new Dictionary<string, List<string>>(StringComparer.Ordinal);
        if (catalogJson != null && run.TryGetValue("catalogClasses", out object catalogClasses) && catalogClasses is IList catalogRows)
            foreach (var row in catalogRows.Cast<object>().Select(Obj))
            {
                var cls = ClassRow(row);
                (cls.Enabled ? data.Classes : data.DisabledClasses).Add(cls);
                var tags = NpcWorldJson.Strings(row, "tags");
                if (cls.Enabled && tags != null) catalogTags[cls.Id] = tags;
            }
        // Named adventure hero rows (phase 6) are catalog content too: they load with the catalog, beside the class rows, and
        // a disabled row (its powers, starters or signatures not scripted yet) is kept aside with its reason.
        if (catalogJson != null && run.TryGetValue("heroRows", out object heroRows) && heroRows is IList heroList)
            foreach (var row in heroList.Cast<object>().Select(Obj))
            {
                var cls = ClassRow(row);
                if (!cls.IsHero) throw new InvalidDataException("run-v1.json: heroRows row " + cls.Id + " must have kind \"hero\"");
                (cls.Enabled ? data.Classes : data.DisabledClasses).Add(cls);
                // NpcWorldJson.Strings returns an empty list for an absent key: a row with no "tags" reads its primary class's
                // (DungeonRunData.TagsOf), so only a present key is an entry of its own.
                if (cls.Enabled && row.ContainsKey("tags")) catalogTags[cls.Id] = NpcWorldJson.Strings(row, "tags");
            }

        foreach (var row in NpcWorldJson.List(run, "treasures").Cast<object>().Select(Obj))
            data.Treasures.Add(new DungeonRunTreasure
            {
                Id = NpcWorldJson.Text(row, "id"),
                Rarity = NpcWorldJson.Text(row, "rarity"),
                Universal = NpcWorldJson.Boolean(row, "universal"),
                Active = NpcWorldJson.Boolean(row, "active"),
                Offered = NpcWorldJson.Boolean(row, "offered", true),
                UpgradesTo = NpcWorldJson.Text(row, "upgradesTo", false),
                Legacy = NpcWorldJson.Boolean(row, "legacy"),
                Tags = NpcWorldJson.Strings(row, "tags") ?? new List<string>(),
                Scope = ParseScope(row),
                Signature = NpcWorldJson.Boolean(row, "signature"),
                Unlock = NpcWorldJson.Text(row, "unlock", false),
                UpgradeUnlock = NpcWorldJson.Text(row, "upgradeUnlock", false),
                UpgradeOn = NpcWorldJson.Text(row, "upgradeOn", false) ?? DungeonRunTreasure.UpgradeOnFloors,
                UpgradeSlot = NpcWorldJson.Text(row, "upgradeSlot", false) ?? DungeonRunTreasure.SlotDeck,
                Pool = NpcWorldJson.Text(row, "pool", false),
                Runs = NpcWorldJson.Text(row, "runs", false) ?? DungeonRunTreasure.RunsAll,
            });
        if (run.TryGetValue("powerUpgrades", out object powerUpgrades) && powerUpgrades is IList powerUpgradeRows)
            foreach (var row in powerUpgradeRows.Cast<object>().Select(Obj))
            {
                var up = new DungeonRunPowerUpgrade
                {
                    From = NpcWorldJson.Text(row, "from"), To = NpcWorldJson.Text(row, "to"),
                    On = NpcWorldJson.Text(row, "on", false) ?? DungeonRunTreasure.UpgradeOnActClear,
                };
                if (data.PowerUpgrades.ContainsKey(up.From)) throw new InvalidDataException("run-v1.json: powerUpgrades lists " + up.From + " twice");
                data.PowerUpgrades[up.From] = up;
            }
        // Phase 7: the teammate registry and the shrine-upgrade pool (data only; the validator checks both).
        if (run.TryGetValue("teammates", out object teammates) && teammates is IDictionary<string, object> teammateRows)
            foreach (var pair in teammateRows)
                data.Teammates[pair.Key] = ((IList)pair.Value).Cast<object>().Select(v => (string)v).ToList();
        if (run.TryGetValue("shrineUpgrades", out object upgrades) && upgrades is IList upgradeRows)
            data.ShrineUpgrades = upgradeRows.Cast<object>().Select(v => (string)v).ToList();

        foreach (var pair in Obj(run["classTags"]))
            data.ClassTags[pair.Key] = ((IList)pair.Value).Cast<object>().Select(v => (string)v).ToList();
        foreach (var pair in catalogTags)
        {
            if (data.ClassTags.ContainsKey(pair.Key)) throw new InvalidDataException("run-v1.json: catalog class " + pair.Key + " has tags in classTags too");
            data.ClassTags[pair.Key] = pair.Value;
        }

        foreach (var row in NpcWorldJson.List(run, "bosses").Cast<object>().Select(Obj))
        {
            int health = NpcWorldJson.Integer(row, "health", 0);
            int band = NpcWorldJson.Integer(row, "band", 0);
            bool final = NpcWorldJson.Boolean(row, "final");
            int manaCap = NpcWorldJson.Integer(row, "bossManaCap", -1);
            data.Bosses.Add(new DungeonRunBoss
            {
                // NpcWorldJson.Strings returns an empty list for an absent key: the band/final default needs the key's absence.
                Pools = row.ContainsKey("pools") ? NpcWorldJson.Strings(row, "pools", true) : new List<string> { final ? DungeonRunSchedules.FinalPool : "band" + band },
                Provenance = NpcWorldJson.Text(row, "provenance", false) ?? "solostone",
                Family = NpcWorldJson.Text(row, "family", false),
                FixedHealth = NpcWorldJson.Boolean(row, "fixedHealth"),
                BossManaCap = manaCap >= 0 ? manaCap : (int?)null,
                IncompatibleModifiers = NpcWorldJson.Strings(row, "incompatibleModifiers") ?? new List<string>(),
                Id = NpcWorldJson.Text(row, "id"),
                Name = NpcWorldJson.Text(row, "name"),
                Band = NpcWorldJson.Integer(row, "band", 0),
                Final = NpcWorldJson.Boolean(row, "final"),
                Challenge = NpcWorldJson.Boolean(row, "challenge"),
                HeroCard = NpcWorldJson.Text(row, "hero"),
                Power = NpcWorldJson.Text(row, "power", false),
                Health = health > 0 ? health : (int?)null,
                Deck = NpcWorldJson.Text(row, "deck"),
                Unlock = NpcWorldJson.Text(row, "unlock", false),
                Archetype = NpcWorldJson.Text(row, "archetype", false),
            });
        }

        foreach (var pair in Obj(run["unlocks"]))
            data.Unlocks[pair.Key] = ParseCondition(Obj(pair.Value));
        // The per-class ladder (design R13): one template, expanded to "<class>_<step>" keys scoped to that class.
        if (run.TryGetValue("classUnlocks", out object ladder) && ladder != null)
            foreach (var step in Obj(ladder))
                foreach (var cls in data.Classes)
                {
                    string key = cls.Id.ToLowerInvariant() + "_" + step.Key;
                    if (data.Unlocks.ContainsKey(key)) throw new InvalidDataException("run-v1.json: unlock " + key + " is defined twice");
                    var condition = ParseCondition(Obj(step.Value));
                    ScopeToClass(condition, cls.Id);
                    data.Unlocks[key] = condition;
                }
        if (run.TryGetValue("legacy", out object legacyValue) && legacyValue != null)
        {
            var legacy = Obj(legacyValue);
            if (legacy.TryGetValue("heroes", out object heroes) && heroes != null)
                foreach (var pair in Obj(heroes))
                {
                    var row = Obj(pair.Value);
                    data.LegacyHeroes[pair.Key] = new DungeonRunLegacyHero
                    {
                        Class = NpcWorldJson.Text(row, "class"),
                        Power = NpcWorldJson.Text(row, "power", false),
                    };
                }
            if (legacy.TryGetValue("unlocks", out object unlocks) && unlocks != null)
                foreach (var pair in Obj(unlocks))
                    data.LegacyUnlocks[pair.Key] = ((IList)pair.Value).Cast<object>().Select(v => (string)v).ToList();
        }

        var pool = Obj(NpcWorldJson.Parse(poolJson));
        if (NpcWorldJson.Integer(pool, "schemaVersion") != SchemaVersion) throw new InvalidDataException("pool-v1.json: unsupported schemaVersion");
        DungeonRunStarterDeck DeckRow(IDictionary<string, object> row) => new DungeonRunStarterDeck
        {
            Id = NpcWorldJson.Text(row, "id"),
            Class = NpcWorldJson.Text(row, "class"),
            Name = NpcWorldJson.Text(row, "name"),
            Description = NpcWorldJson.Text(row, "description"),
            Unlock = NpcWorldJson.Text(row, "unlock", false),
            TreasureTags = NpcWorldJson.Strings(row, "treasureTags") ?? new List<string>(),
            Generator = NpcWorldJson.Text(row, "generator", false),
            DisplayCard = NpcWorldJson.Text(row, "displayCard", false),
            Shrine = NpcWorldJson.Text(row, "shrine", false),
            // A generated deck lists no cards (the key may be absent); a fixed deck must list them.
            Cards = row.ContainsKey("generator") ? NpcWorldJson.Strings(row, "cards") ?? new List<string>() : NpcWorldJson.Strings(row, "cards", true),
        };
        foreach (var row in NpcWorldJson.List(pool, "starterDecks").Cast<object>().Select(Obj))
            data.Decks.Add(DeckRow(row));
        // The catalog class rows' starter decks (run-v1.json "catalogStarterDecks": the Tombs of Terror explorers' decks)
        // load with their rows: a disabled row's decks are kept aside with it.
        if (catalogJson != null && run.TryGetValue("catalogStarterDecks", out object catalogDecks) && catalogDecks is IList catalogDeckRows)
        {
            var disabled = new HashSet<string>(data.DisabledClasses.SelectMany(c => c.Decks), StringComparer.Ordinal);
            foreach (var row in catalogDeckRows.Cast<object>().Select(Obj))
            {
                var deck = DeckRow(row);
                (disabled.Contains(deck.Id) ? data.DisabledDecks : data.Decks).Add(deck);
            }
        }
        // A treasure scoped only to catalog starter decks (phase 6: a named hero's own treasures, scoped to the hero row's starter)
        // is catalog content as well: without the catalog its decks do not load, so neither does it.
        if (catalogJson == null && run.TryGetValue("catalogStarterDecks", out object unloadedDecks) && unloadedDecks is IList unloadedRows)
        {
            var catalogDeckIds = new HashSet<string>(unloadedRows.Cast<object>().Select(Obj).Select(r => NpcWorldJson.Text(r, "id")), StringComparer.Ordinal);
            data.Treasures.RemoveAll(t => t.Scope.Decks.Count > 0 && t.Scope.Classes.Count == 0 && t.Scope.Powers.Count == 0
                && t.Scope.Decks.All(catalogDeckIds.Contains));
        }
        // Likewise a treasure scoped only to catalog rows (phase 6 F11: the Tombs signatures and Pack Mule, scoped to the dual
        // rows) and an unlock condition of a catalog row (a signature's unlock): without the catalog their rows do not load.
        if (catalogJson == null)
        {
            var catalogRowIds = new HashSet<string>(StringComparer.Ordinal);
            foreach (string key in new[] { "catalogClasses", "heroRows" })
                if (run.TryGetValue(key, out object rowsValue) && rowsValue is IList rowList)
                    foreach (var row in rowList.Cast<object>().Select(Obj)) catalogRowIds.Add(NpcWorldJson.Text(row, "id"));
            data.Treasures.RemoveAll(t => t.Scope.Classes.Count > 0 && t.Scope.Decks.Count == 0 && t.Scope.Powers.Count == 0
                && t.Scope.Classes.All(catalogRowIds.Contains));
            foreach (string key in data.Unlocks.Where(u => u.Value.Class != null && catalogRowIds.Contains(u.Value.Class)).Select(u => u.Key).ToList())
                data.Unlocks.Remove(key);
        }
        foreach (var row in NpcWorldJson.List(pool, "bundles").Cast<object>().Select(Obj))
        {
            string cls = NpcWorldJson.Text(row, "class"), theme = NpcWorldJson.Text(row, "theme"), id = NpcWorldJson.Text(row, "id");
            data.Bundles.Add(new DungeonRunBundle
            {
                Id = id, Class = cls, Theme = theme, Label = FixedLabel(theme), LabelKey = LabelKeyOf(FixedLabel(theme)),
                Cards = NpcWorldJson.Strings(row, "cards", true),
                Classes = new List<string> { cls }, Themes = new List<string> { theme },
            });
        }
        if (catalogJson != null) ParseCatalog(data, catalogJson);
        foreach (var pair in Obj(pool["bossDecks"]))
            data.BossDecks[pair.Key] = ((IList)pair.Value).Cast<object>().Select(v => (string)v).ToList();

        // NPC library decks named by a boss: expand {id, count} rows.
        var wanted = new HashSet<string>(data.Bosses.Select(b => b.Deck).Where(d => !data.BossDecks.ContainsKey(d)));
        if (wanted.Count > 0)
        {
            var npc = Obj(NpcWorldJson.Parse(npcDecksJson ?? throw new InvalidDataException("Boss decks need data/npc/decks-v1.json")));
            foreach (var row in NpcWorldJson.List(npc, "decks").Cast<object>().Select(Obj))
            {
                string id = NpcWorldJson.Text(row, "id");
                if (!wanted.Contains(id)) continue;
                var cards = new List<string>();
                foreach (var entry in NpcWorldJson.List(row, "cards").Cast<object>().Select(Obj))
                    cards.AddRange(Enumerable.Repeat(NpcWorldJson.Text(entry, "id"), NpcWorldJson.Integer(entry, "count")));
                data.BossDecks[id] = cards;
                if (row.TryGetValue("tags", out object tagsValue) && tagsValue is IDictionary<string, object> tags)
                {
                    string archetype = NpcWorldJson.Text(tags, "archetype", false);
                    foreach (var boss in data.Bosses.Where(b => b.Deck == id && b.Archetype == null)) boss.Archetype = archetype;
                }
                // "sideboards": one {owner, cards} object or a list of them.
                if (row.TryGetValue("sideboards", out object boards) && boards != null)
                {
                    var map = new Dictionary<string, string[]>();
                    foreach (var board in (boards is IList list ? list.Cast<object>() : new[] { boards }).Select(Obj))
                        map[NpcWorldJson.Text(board, "owner")] = NpcWorldJson.List(board, "cards").Cast<object>().Select(Obj)
                            .SelectMany(e => Enumerable.Repeat(NpcWorldJson.Text(e, "id"), NpcWorldJson.Integer(e, "count"))).ToArray();
                    if (map.Count > 0) data.BossSideboards[id] = map;
                }
            }
        }
        return data;
    }

    /// <summary>The data schema both files carry (2: classes, starter decks, treasure scopes).</summary>
    internal const int SchemaVersion = 2;

    /// <summary>The schema catalog-v1.json carries.</summary>
    internal const int CatalogSchemaVersion = 1;

    /// <summary>The message the loader raises when catalog-v1.json does not match pool-v1.json.</summary>
    internal const string StaleCatalog = "catalog-v1.json is stale: run tools/dungeon-run-catalog";

    /// <summary>
    /// Catalog entry ids ("dr.druid.mana-growth"): lower-case letters, digits, '.', '_' and '-'. The legacy bundle ids
    /// ("bundle_druid_spells") keep their form; ids never hold '@' (the cooldown separator), ':' or spaces.
    /// </summary>
    internal static readonly System.Text.RegularExpressions.Regex EntryIdPattern =
        new System.Text.RegularExpressions.Regex("^[a-z0-9][a-z0-9._-]*$", System.Text.RegularExpressions.RegexOptions.CultureInvariant);

    /// <summary>The label of a fixed SoloStone bundle: its theme, first letter upper-cased ("spells" -> "Spells").</summary>
    internal static string FixedLabel(string theme) =>
        string.IsNullOrEmpty(theme) ? theme : char.ToUpperInvariant(theme[0]) + theme.Substring(1);

    /// <summary>
    /// The grouping key of a label: lower case, apostrophes dropped, every other run of non-letters and non-digits one space,
    /// trimmed ("Cult of C'Thun" -> "cult of cthun", "Stomp, Stomp, STOMP" -> "stomp stomp stomp"). Typo fixes are curation's.
    /// </summary>
    internal static string LabelKeyOf(string label)
    {
        string lower = (label ?? "").ToLowerInvariant().Replace("'", "").Replace("\u2019", "");
        return System.Text.RegularExpressions.Regex.Replace(lower, "[^a-z0-9]+", " ").Trim();
    }

    /// <summary>
    /// SHA-256 (lower-case hex) over the fixed bundles in order, one line each: "id\tclass\ttheme\tcard,card,card\n" (UTF-8).
    /// The catalog tool stores it as poolBundlesHash; the loader recomputes it from pool-v1.json and from the catalog.
    /// </summary>
    internal static string PoolBundlesHash(IEnumerable<DungeonRunBundle> bundles)
    {
        var text = new System.Text.StringBuilder();
        foreach (var b in bundles)
            text.Append(b.Id).Append('\t').Append(b.Class).Append('\t').Append(b.Theme).Append('\t').Append(string.Join(",", b.Cards)).Append('\n');
        using (var sha = System.Security.Cryptography.SHA256.Create())
        {
            byte[] hash = sha.ComputeHash(new System.Text.UTF8Encoding(false).GetBytes(text.ToString()));
            var hex = new System.Text.StringBuilder(hash.Length * 2);
            foreach (byte b in hash) hex.Append(b.ToString("x2", System.Globalization.CultureInfo.InvariantCulture));
            return hex.ToString();
        }
    }

    // Replaces data.Bundles (the pool's bundles) with the catalog's entries after checking the catalog carries those bundles.
    private static void ParseCatalog(DungeonRunData data, string catalogJson)
    {
        var catalog = Obj(NpcWorldJson.Parse(catalogJson));
        if (NpcWorldJson.Integer(catalog, "schemaVersion") != CatalogSchemaVersion) throw new InvalidDataException("catalog-v1.json: unsupported schemaVersion");
        string poolHash = PoolBundlesHash(data.Bundles);
        if (NpcWorldJson.Text(catalog, "poolBundlesHash") != poolHash) throw new InvalidDataException(StaleCatalog + " (pool bundles changed)");
        var entries = new List<DungeonRunBundle>();
        var seen = new HashSet<string>(StringComparer.Ordinal);
        foreach (var row in NpcWorldJson.List(catalog, "entries").Cast<object>().Select(Obj))
        {
            var e = new DungeonRunBundle
            {
                Id = NpcWorldJson.Text(row, "id"),
                Kind = NpcWorldJson.Text(row, "draw"),
                Legacy = NpcWorldJson.Boolean(row, "legacy"),
                Label = NpcWorldJson.Text(row, "label"),
                LabelKey = NpcWorldJson.Text(row, "labelKey"),
                Classes = NpcWorldJson.Strings(row, "classes", true),
                Themes = NpcWorldJson.Strings(row, "themes", true),
                Distinct = NpcWorldJson.Boolean(row, "distinct"),
                Weight = NpcWorldJson.Integer(row, "weight", 1),
                AvgCost = NpcWorldJson.Number(row, "avgCost", 0),
                Offerable = NpcWorldJson.Boolean(row, "offerable", true),
                Withdrawn = NpcWorldJson.Text(row, "withdrawn", false),
                Cards = NpcWorldJson.Strings(row, "cards") ?? new List<string>(),
            };
            if (e.Kind != DungeonRunBundle.KindFixed && e.Kind != DungeonRunBundle.KindPool) throw new InvalidDataException("catalog-v1.json: " + e.Id + " has draw " + e.Kind);
            if (!seen.Add(e.Id)) throw new InvalidDataException("catalog-v1.json: entry " + e.Id + " is listed twice");
            e.Class = e.Classes.FirstOrDefault() ?? "NEUTRAL";
            e.Theme = e.Themes.FirstOrDefault();
            if (row.TryGetValue("requires", out object req) && req is IDictionary<string, object> requires)
            {
                e.ClassesAll = NpcWorldJson.Strings(requires, "classesAll") ?? new List<string>();
                e.RequiresMechanic = NpcWorldJson.Text(requires, "mechanic", false);
            }
            if (row.TryGetValue("members", out object members) && members is IList memberList)
                foreach (var m in memberList.Cast<object>().Select(Obj))
                    e.Candidates.Add(new DungeonRunCandidate
                    {
                        Id = NpcWorldJson.Text(m, "id"),
                        WikiId = NpcWorldJson.Text(m, "wikiId", false),
                        Weight = NpcWorldJson.Integer(m, "weight", 1),
                        Grant = NpcWorldJson.Boolean(m, "grant"),
                    });
            if (row.TryGetValue("provenance", out object prov) && prov is IList provList)
                foreach (var p in provList.Cast<object>().Select(Obj))
                    e.Provenance.Add(new DungeonRunProvenance
                    {
                        Adventure = NpcWorldJson.Text(p, "adventure"),
                        Hero = NpcWorldJson.Text(p, "hero", false),
                        Label = NpcWorldJson.Text(p, "label", false),
                        LabelCardId = NpcWorldJson.Text(p, "labelCardId", false),
                        Membership = NpcWorldJson.Text(p, "membership", false),
                        Source = NpcWorldJson.Text(p, "source", false),
                    });
            if (row.TryGetValue("quest", out object quest) && quest is IDictionary<string, object> q)
                e.Quest = new DungeonRunQuest { CardId = NpcWorldJson.Text(q, "cardId"), OnFirstTake = NpcWorldJson.Boolean(q, "onFirstTake") };
            entries.Add(e);
        }
        // The fixed legacy entries must be the pool's bundles, in pool order.
        if (PoolBundlesHash(entries.Where(b => b.Legacy)) != poolHash) throw new InvalidDataException(StaleCatalog + " (its fixed entries differ from pool-v1.json)");
        data.Bundles = entries;
        data.CatalogVersion = NpcWorldJson.Integer(catalog, "catalogVersion");
    }

    private static DungeonRunScope ParseScope(IDictionary<string, object> row)
    {
        var scope = new DungeonRunScope();
        if (!row.TryGetValue("scope", out object value) || value == null) return scope;
        var map = Obj(value);
        scope.Classes = NpcWorldJson.Strings(map, "classes") ?? new List<string>();
        scope.Decks = NpcWorldJson.Strings(map, "decks") ?? new List<string>();
        scope.Powers = NpcWorldJson.Strings(map, "powers") ?? new List<string>();
        return scope;
    }

    // A ladder step is scoped to its class, and so is every allOf/anyOf branch that names no class of its own ("win": a run won
    // OR an act major beaten, both with this class).
    private static void ScopeToClass(DungeonRunCondition condition, string cls)
    {
        condition.Class = condition.Class ?? cls;
        foreach (var sub in (condition.AllOf ?? new List<DungeonRunCondition>()).Concat(condition.AnyOf ?? new List<DungeonRunCondition>()))
            ScopeToClass(sub, cls);
    }

    private static DungeonRunCondition ParseCondition(IDictionary<string, object> row)
    {
        var c = new DungeonRunCondition();
        if (row.ContainsKey("floorReached")) c.FloorReached = NpcWorldJson.Integer(row, "floorReached");
        if (row.ContainsKey("runsWon")) c.RunsWon = NpcWorldJson.Integer(row, "runsWon");
        if (row.ContainsKey("classesWon")) c.ClassesWon = NpcWorldJson.Integer(row, "classesWon");
        if (row.ContainsKey("majorsCleared")) c.MajorsCleared = NpcWorldJson.Integer(row, "majorsCleared");
        c.Class = NpcWorldJson.Text(row, "class", false);
        if (row.ContainsKey("allOf")) c.AllOf = NpcWorldJson.List(row, "allOf").Cast<object>().Select(v => ParseCondition(Obj(v))).ToList();
        if (row.ContainsKey("anyOf")) c.AnyOf = NpcWorldJson.List(row, "anyOf").Cast<object>().Select(v => ParseCondition(Obj(v))).ToList();
        return c;
    }

    private static IDictionary<string, object> Obj(object value) =>
        value as IDictionary<string, object> ?? throw new InvalidDataException("Expected JSON object.");

    private static int[] Ints(IDictionary<string, object> row, string key) =>
        NpcWorldJson.List(row, key).Cast<object>().Select(v => Convert.ToInt32(v, System.Globalization.CultureInfo.InvariantCulture)).ToArray();

    private static Dictionary<string, string> StringMap(IDictionary<string, object> row, string key)
    {
        var result = new Dictionary<string, string>();
        if (row.TryGetValue(key, out object value) && value is IDictionary<string, object> map)
            foreach (var pair in map) result[pair.Key] = (string)pair.Value;
        return result;
    }
}

// ---------------------------------------------------------------------------------------------------------- act schedule
// schedule-v1.json (phases 4 and 5): acts of floors with combat pools, a major boss, health and start-mana curves, treasure,
// tavern and modifier nodes, and the modifiers. Floor stays a global combat floor index across the run; the flattened node
// list adds the tavern and modifier nodes, which consume no floor.

// Anomaly (phase 8, scheduleVersion 3): the act's anomaly offer (two rolled rules or none); appended, so the others keep their values.
internal enum DungeonRunNodeKind { Combat, Major, Tavern, Modifier, Anomaly }

/// <summary>
/// One step of a schedule. <see cref="Floor"/> is the global combat floor: a combat or major node's own floor, a tavern or
/// modifier node's next fight (so <c>DungeonRunState.Floor</c> never goes back). <see cref="Act"/> is 1-based;
/// <see cref="FloorInAct"/> is 1-based too (for a tavern or modifier node: the floor in the act of the fight it precedes).
/// </summary>
internal sealed class DungeonRunNode
{
    internal int Index, Act, FloorInAct, Floor;
    internal DungeonRunNodeKind Kind;
    /// <summary>A combat or major win here opens a treasure draft (act "treasureAfter", or "passiveAtStart" on the act's first floor).</summary>
    internal bool TreasureDraft;
    /// <summary>The treasure draft offers passive treasures only (the act's "passiveAtStart" draft on its first floor).</summary>
    internal bool PassiveOnly;
    /// <summary>
    /// Phase 7 (scheduleVersion 2): a win here opens a teammate draft (act "teammateAfter"), after the treasure draft, on a run
    /// with a board shrine (DungeonRunState.BoardShrine). A draft flag on a fight node, like <see cref="TreasureDraft"/>: no node.
    /// </summary>
    internal bool TeammateDraft;
    /// <summary>Phase 7 (scheduleVersion 2): a win here opens a shrine-upgrade draft (act "shrineUpgradeAfter") on a shrine run.</summary>
    internal bool ShrineUpgradeDraft;
    internal bool IsFight => Kind == DungeonRunNodeKind.Combat || Kind == DungeonRunNodeKind.Major;
}

internal sealed class DungeonRunCombatSlot
{
    internal string Pool;
    internal int Count;
}

internal sealed class DungeonRunAct
{
    internal string Id, Name;
    internal int Floors;
    internal List<DungeonRunCombatSlot> Combat = new List<DungeonRunCombatSlot>();
    internal string MajorPool;
    internal int[] BossHealth = new int[0], BossMana = new int[0], TreasureAfter = new int[0], Taverns = new int[0];
    /// <summary>Phase 7 (read for scheduleVersion 2 and later): the floors whose win opens a teammate / shrine-upgrade draft.</summary>
    internal int[] TeammateAfter = new int[0], ShrineUpgradeAfter = new int[0];
    internal bool PassiveAtStart, ModifierAtStart;
    internal int DraftOptions = 3, DraftTakes = 3, TavernGold, TavernOffers;

    // ---- phase 8 (read for scheduleVersion 3 and later; a version-1 or version-2 file never has them)
    /// <summary>The act opens with an anomaly node (before its modifier node): two rolled global rules or none.</summary>
    internal bool AnomalyAtStart;
    /// <summary>The twist rules one of which may be rolled for this act at NewRun, and the chance in percent.</summary>
    internal List<string> TwistPool = new List<string>();
    internal int TwistChance;
    /// <summary>A finale act (synthesized from the schedule's enabled "finale"): its bosses in fight order, one per floor, no draw and no card draft.</summary>
    internal List<string> FixedBosses = new List<string>();
    /// <summary>A finale act opens with a tavern node (finale "tavernBefore").</summary>
    internal bool TavernAtStart;
    /// <summary>The run player's relay heroes enter in the finale's fights (finale "heroRelay").</summary>
    internal bool HeroRelay;
    internal bool IsFinale => FixedBosses.Count > 0;
}

/// <summary>
/// A global rule (schedule-v1.json "rules", scheduleVersion 3): an anomaly (offered at an act's anomaly node) or a twist
/// (rolled per act at NewRun). The id is the rule's card id. Kept apart from the modifiers, so modifier offers and every
/// run saved on an older schedule version are untouched.
/// </summary>
internal sealed class DungeonRunGlobalRule
{
    internal const string KindAnomaly = "anomaly", KindTwist = "twist", ScopeAct = "act", ScopeRun = "run",
        EffectMatch = "match", EffectRun = "run", StatusAdmitted = "admitted", StatusRejected = "rejected";
    /// <summary>The "no rule" option of an anomaly offer (never an active rule).</summary>
    internal const string None = "none";
    internal string Id, Kind = KindAnomaly, Provenance, Scope = ScopeAct, Effect = EffectMatch, Status = StatusAdmitted, Reason;
    internal int Weight = 1;
    /// <summary>Rule ids it never shares an act with (checked both ways).</summary>
    internal List<string> IncompatibleRules = new List<string>();
    /// <summary>Boss flags (DungeonRunEncounterData.Flags) it is never active with: no boss pre-rolled for the act has one.</summary>
    internal List<string> IncompatibleFlags = new List<string>();
    /// <summary>Never on a run that holds a board shrine (a board-limit or permanent-Immune rule).</summary>
    internal bool NoBoardShrine;
    /// <summary>Modifier ids it never shares an act with (ULDA_715 Bountiful and mod_open_road).</summary>
    internal List<string> IncompatibleModifiers = new List<string>();
    /// <summary>
    /// Run class ids (DungeonRunClass.Id) it is never active for (family 05: DALA_833 The Carts and Darius Crowley, whose
    /// Cannons already take board slots): the run itself, beside <see cref="NoBoardShrine"/>.
    /// </summary>
    internal List<string> IncompatibleClasses = new List<string>();
    internal bool Admitted => Status == StatusAdmitted;
    internal bool RunScope => Scope == ScopeRun;
}

/// <summary>A schedule modifier: a whitelist of numeric knobs, active for the rest of the act it is taken in.</summary>
internal sealed class DungeonRunModifier
{
    internal string Id, Name;
    internal int BossHealthDelta, DraftOptionsDelta, TavernGoldDelta, BossManaDelta, PlayerHealthDelta, OpeningHandBonus;
    internal bool ExtraTreasureAfterMajor;
    /// <summary>Knob keys the row named that are not in <see cref="DungeonRunSchedules.ModifierKnobs"/> (the validator refuses them).</summary>
    internal List<string> UnknownKnobs = new List<string>();
}

internal sealed class DungeonRunSchedule
{
    internal string Id;
    internal int DeckMin = 10, DeckMax = 50;
    internal List<DungeonRunAct> Acts = new List<DungeonRunAct>();
    /// <summary>The reference finale (phase 8: fixed bosses, hero relay); data only while disabled.</summary>
    internal bool FinaleEnabled, FinaleHeroRelay;
    internal List<string> FinaleBosses = new List<string>();
    /// <summary>
    /// The ScheduleVersion a new run on this schedule is stamped with (schedule "version"; absent = the file's
    /// scheduleVersion). A schedule an older version released unchanged keeps that version's stamp (acts-v2: 2), so a new run
    /// on it is exactly a run of that version: it loads through DungeonRun.ScheduleFor's older-version branch and never sees a
    /// later version's nodes or rules.
    /// </summary>
    internal int StampVersion;
    /// <summary>How an act's bosses are drawn: null (the released draw: one shuffle per slot) or <see cref="DrawProvenanceMix"/>.</summary>
    internal string Draw;
    internal const string DrawProvenanceMix = "provenance-mix";
    internal bool MixesProvenance => Draw == DrawProvenanceMix;
    private List<DungeonRunNode> nodes;

    /// <summary>The flattened node list (see <see cref="Flatten"/>), built once.</summary>
    internal IReadOnlyList<DungeonRunNode> Nodes => nodes ?? (nodes = Flatten());
    /// <summary>The combat floors (combat and major nodes) of the whole run.</summary>
    internal int FloorCount => Acts.Sum(a => a.Floors);

    /// <summary>The fight node of global floor <paramref name="floor"/>, or null.</summary>
    internal DungeonRunNode FightAt(int floor) => Nodes.FirstOrDefault(n => n.IsFight && n.Floor == floor);

    /// <summary>
    /// Node order inside an act: its modifier node (when "modifierAtStart"); its combat floors, a tavern node after each floor
    /// listed in "taverns"; the major on its last floor. A draft after a major opens before the next act's nodes.
    /// </summary>
    internal List<DungeonRunNode> Flatten()
    {
        var list = new List<DungeonRunNode>();
        int floor = 0;
        for (int a = 0; a < Acts.Count; a++)
        {
            var act = Acts[a];
            // Phase 8: a finale's tavern, then the act's anomaly node, both before the modifier node (absent on every older schedule).
            if (act.TavernAtStart) list.Add(new DungeonRunNode { Kind = DungeonRunNodeKind.Tavern, Act = a + 1, FloorInAct = 1, Floor = floor + 1 });
            if (act.AnomalyAtStart) list.Add(new DungeonRunNode { Kind = DungeonRunNodeKind.Anomaly, Act = a + 1, FloorInAct = 1, Floor = floor + 1 });
            if (act.ModifierAtStart) list.Add(new DungeonRunNode { Kind = DungeonRunNodeKind.Modifier, Act = a + 1, FloorInAct = 1, Floor = floor + 1 });
            for (int f = 1; f <= act.Floors; f++)
            {
                floor++;
                bool passive = act.PassiveAtStart && f == 1;
                list.Add(new DungeonRunNode
                {
                    Kind = f == act.Floors ? DungeonRunNodeKind.Major : DungeonRunNodeKind.Combat, Act = a + 1, FloorInAct = f, Floor = floor,
                    TreasureDraft = passive || act.TreasureAfter.Contains(f), PassiveOnly = passive && !act.TreasureAfter.Contains(f),
                    TeammateDraft = act.TeammateAfter.Contains(f), ShrineUpgradeDraft = act.ShrineUpgradeAfter.Contains(f),
                });
                if (f < act.Floors && act.Taverns.Contains(f))
                    list.Add(new DungeonRunNode { Kind = DungeonRunNodeKind.Tavern, Act = a + 1, FloorInAct = f + 1, Floor = floor + 1 });
            }
        }
        for (int i = 0; i < list.Count; i++) list[i].Index = i;
        return list;
    }
}

/// <summary>schedule-v1.json: the schedules, the default one and the modifiers.</summary>
internal sealed class DungeonRunSchedules
{
    /// <summary>The run state's ScheduleVersion of a run on these schedules ("scheduleVersion").</summary>
    internal int ScheduleVersion;
    internal string Default;
    internal Dictionary<string, DungeonRunSchedule> Schedules = new Dictionary<string, DungeonRunSchedule>(StringComparer.Ordinal);
    internal List<DungeonRunModifier> Modifiers = new List<DungeonRunModifier>();
    /// <summary>
    /// Phase 8 ("defaults", scheduleVersion 3): the schedules a new run rolls one of from its seed (DungeonRun.DefaultSchedule);
    /// empty = always <see cref="Default"/>.
    /// </summary>
    internal List<string> Defaults = new List<string>();
    /// <summary>Phase 8 ("poolSets"): a named union of boss pools a combat slot or a major may draw from ("mix-1": band1 + enc-t1).</summary>
    internal Dictionary<string, List<string>> PoolSets = new Dictionary<string, List<string>>(StringComparer.Ordinal);
    /// <summary>Phase 8 ("rules"): the global rules (anomalies and twists), in file order.</summary>
    internal List<DungeonRunGlobalRule> Rules = new List<DungeonRunGlobalRule>();
    internal DungeonRunGlobalRule Rule(string id) => Rules.FirstOrDefault(r => r.Id == id);

    /// <summary>
    /// The boss is a member of <paramref name="pool"/>: a pool set's union when the name is one (<see cref="PoolSets"/>), else
    /// the plain pool (<see cref="InPool"/>).
    /// </summary>
    internal bool Member(DungeonRunBoss boss, string pool) =>
        pool != null && PoolSets.TryGetValue(pool, out var set) ? set.Any(p => InPool(boss, p)) : InPool(boss, pool);

    /// <summary>
    /// The node shape (<see cref="ShapeDigest"/>) of every schedule each released scheduleVersion shipped. A saved act run keeps
    /// its Node, Floor and boss sequence as indexes into its schedule's flattened nodes, and only the run's ScheduleVersion pins
    /// them (DungeonRun.ScheduleFor), so the validator refuses a schedule whose shape differs from the one recorded for the
    /// loaded version: an edit that adds, moves or removes a node, changes an act's floors, treasure nodes or combat pools, or
    /// drops a released schedule must bump scheduleVersion (and keep the old version loadable for runs saved on it). Tuning
    /// values (health and mana curves, gold, offers, draft options) are not part of the shape.
    /// </summary>
    internal static readonly IReadOnlyDictionary<int, IReadOnlyDictionary<string, string>> ReleasedShapes =
        new Dictionary<int, IReadOnlyDictionary<string, string>>
        {
            [1] = new Dictionary<string, string>(StringComparer.Ordinal) { ["acts-v1"] = "3293D82FA6BD48B3", ["act1"] = "3673E8AE7F914E4F" },
            // Phase 7: acts-v2 is acts-v1 plus the teammate and shrine-upgrade draft flags; acts-v1 and act1 ship unchanged, so a
            // run saved on version 1 keeps its nodes (DungeonRun.ScheduleFor loads it, with no phase-7 draft).
            [2] = new Dictionary<string, string>(StringComparer.Ordinal) { ["acts-v1"] = "3293D82FA6BD48B3", ["act1"] = "3673E8AE7F914E4F", ["acts-v2"] = "8D594CBB45303A53" },
            // Phase 8: acts-v3h and acts-v3t (encounter pool sets, anomaly nodes) join; the three older schedules ship unchanged
            // and keep their own stamps (DungeonRunSchedule.StampVersion), so a run saved on version 1 or 2 keeps its nodes. The
            // two v3 digests are the shapes with the finales still disabled: the family that enables a finale re-pins its schedule
            // here (nothing is released until phase 8 closes).
            [3] = new Dictionary<string, string>(StringComparer.Ordinal)
            {
                ["acts-v1"] = "3293D82FA6BD48B3", ["act1"] = "3673E8AE7F914E4F", ["acts-v2"] = "8D594CBB45303A53",
                ["acts-v3h"] = "FF4FEC05953AA0DE", ["acts-v3t"] = "FF4FEC05953AA0DE",
            },
        };

    /// <summary>The oldest scheduleVersion a saved act run may be on and still load (every released version from it on keeps its shapes).</summary>
    internal const int OldestScheduleVersion = 1;

    /// <summary>
    /// A schedule's shape as text: each flattened node (kind, act.floor-in-act@floor, t = treasure draft, p = passive only,
    /// m = teammate draft, u = shrine-upgrade draft; the last two are phase 7 and absent from every version-1 schedule, so
    /// those digests are unchanged), then each act's combat slots and major pool. Phase 8: an anomaly node is kind "A", and a
    /// finale act's fixed bosses follow its major pool ("=id,id"); neither occurs on an older schedule.
    /// </summary>
    internal static string Shape(DungeonRunSchedule schedule) =>
        string.Join(" ", schedule.Nodes.Select(n => n.Kind.ToString().Substring(0, 1) + n.Act + "." + n.FloorInAct + "@" + n.Floor
            + (n.TreasureDraft ? "t" : "") + (n.PassiveOnly ? "p" : "") + (n.TeammateDraft ? "m" : "") + (n.ShrineUpgradeDraft ? "u" : "")))
        + " | " + string.Join(" ", schedule.Acts.Select(a => a.Floors + ":" + string.Join("+", a.Combat.Select(c => c.Pool + "x" + c.Count)) + ">" + a.MajorPool
            + (a.IsFinale ? "=" + string.Join(",", a.FixedBosses) : "")));

    /// <summary>The 64-bit FNV-1a digest of <see cref="Shape"/> (UTF-8), as 16 hex digits.</summary>
    internal static string ShapeDigest(DungeonRunSchedule schedule)
    {
        ulong hash = 14695981039346656037UL;
        foreach (byte b in System.Text.Encoding.UTF8.GetBytes(Shape(schedule))) { hash ^= b; hash *= 1099511628211UL; }
        return hash.ToString("X16", System.Globalization.CultureInfo.InvariantCulture);
    }

    /// <summary>NewRun's schedule id for a legacy run (ScheduleVersion 0) even when schedules are loaded.</summary>
    internal const string LegacyId = "legacy";
    internal const string FinalPool = "final", LeftoverPool = "leftover";
    /// <summary>The start-mana bonus cap of a boss with no "bossManaCap".</summary>
    internal const int DefaultBossManaCap = 3;
    /// <summary>The modifier knobs a row may name: none of them touches a boss's deck, power, passive or hero.</summary>
    internal static readonly string[] ModifierKnobs =
        { "bossHealthDelta", "draftOptionsDelta", "tavernGoldDelta", "bossManaDelta", "playerHealthDelta", "openingHandBonus", "extraTreasureAfterMajor" };

    /// <summary>The boss is a member of <paramref name="pool"/> ("leftover": any band pool, never a final). Here, not in
    /// DungeonRun, because the validator (and so tools/dungeon-run-catalog, which compiles it without DungeonRun) uses it.</summary>
    internal static bool InPool(DungeonRunBoss boss, string pool) =>
        pool == LeftoverPool
            ? !boss.Final && boss.Pools.Any(p => p.StartsWith("band", StringComparison.Ordinal))
            : boss.Pools.Contains(pool);

    internal DungeonRunSchedule Find(string id) => id != null && Schedules.TryGetValue(id, out var s) ? s : null;
    internal DungeonRunModifier Modifier(string id) => Modifiers.FirstOrDefault(m => m.Id == id);

    internal static DungeonRunSchedules Parse(string json)
    {
        var root = NpcWorldJson.Object(NpcWorldJson.Parse(json));
        var result = new DungeonRunSchedules
        {
            ScheduleVersion = NpcWorldJson.Integer(root, "scheduleVersion"),
            Default = NpcWorldJson.Text(root, "default"),
        };
        if (result.ScheduleVersion < 1) throw new InvalidDataException("schedule-v1.json: scheduleVersion must be 1 or more");
        bool v3 = result.ScheduleVersion >= 3;
        if (v3)
        {
            result.Defaults = NpcWorldJson.Strings(root, "defaults") ?? new List<string>();
            if (root.TryGetValue("poolSets", out object sets) && sets is IDictionary<string, object> setRows)
                foreach (var pair in setRows)
                    result.PoolSets[pair.Key] = ((IList)pair.Value).Cast<object>().Select(v => (string)v).ToList();
            if (root.TryGetValue("rules", out object rules) && rules is IList ruleRows)
                foreach (var r in ruleRows.Cast<object>().Select(NpcWorldJson.Object))
                    result.Rules.Add(new DungeonRunGlobalRule
                    {
                        Id = NpcWorldJson.Text(r, "id"), Kind = NpcWorldJson.Text(r, "kind"), Provenance = NpcWorldJson.Text(r, "provenance", false),
                        Scope = NpcWorldJson.Text(r, "scope", false) ?? DungeonRunGlobalRule.ScopeAct,
                        Effect = NpcWorldJson.Text(r, "effect", false) ?? DungeonRunGlobalRule.EffectMatch,
                        Status = NpcWorldJson.Text(r, "status", false) ?? DungeonRunGlobalRule.StatusAdmitted,
                        Reason = NpcWorldJson.Text(r, "reason", false), Weight = NpcWorldJson.Integer(r, "weight", 1),
                        IncompatibleRules = NpcWorldJson.Strings(r, "incompatibleRules") ?? new List<string>(),
                        IncompatibleFlags = NpcWorldJson.Strings(r, "incompatibleFlags") ?? new List<string>(),
                        IncompatibleModifiers = NpcWorldJson.Strings(r, "incompatibleModifiers") ?? new List<string>(),
                        IncompatibleClasses = NpcWorldJson.Strings(r, "incompatibleClasses") ?? new List<string>(),
                        NoBoardShrine = NpcWorldJson.Boolean(r, "noBoardShrine"),
                    });
        }
        var sameActs = new List<KeyValuePair<DungeonRunSchedule, string>>();
        var finales = new Dictionary<DungeonRunSchedule, IDictionary<string, object>>();
        foreach (var pair in NpcWorldJson.Object(root["schedules"]))
        {
            if (pair.Key == LegacyId) throw new InvalidDataException("schedule-v1.json: \"" + LegacyId + "\" is reserved for the fixed eight floors");
            var row = NpcWorldJson.Object(pair.Value);
            var schedule = new DungeonRunSchedule
            {
                Id = pair.Key,
                DeckMin = NpcWorldJson.Integer(row, "deckMin"),
                DeckMax = NpcWorldJson.Integer(row, "deckMax"),
                StampVersion = v3 ? NpcWorldJson.Integer(row, "version", result.ScheduleVersion) : result.ScheduleVersion,
                Draw = v3 ? NpcWorldJson.Text(row, "draw", false) : null,
            };
            // Phase 8: "sameActsAs" shares another schedule's acts (acts-v3t plays acts-v3h's three acts before its own finale).
            // (Read whatever the file's version: a schedule that shares acts lists none of its own.)
            string same = NpcWorldJson.Text(row, "sameActsAs", false);
            if (same != null) sameActs.Add(new KeyValuePair<DungeonRunSchedule, string>(schedule, same));
            foreach (var a in same != null ? new List<IDictionary<string, object>>() : NpcWorldJson.List(row, "acts").Cast<object>().Select(NpcWorldJson.Object).ToList())
            {
                var act = new DungeonRunAct
                {
                    Id = NpcWorldJson.Text(a, "id"), Name = NpcWorldJson.Text(a, "name"),
                    Floors = NpcWorldJson.Integer(a, "floors"),
                    MajorPool = NpcWorldJson.Text(NpcWorldJson.Object(a["major"]), "pool"),
                    BossHealth = Ints(a, "bossHealth"), BossMana = Ints(a, "bossMana"),
                    TreasureAfter = Ints(a, "treasureAfter"), Taverns = Ints(a, "taverns"),
                    PassiveAtStart = NpcWorldJson.Boolean(a, "passiveAtStart"), ModifierAtStart = NpcWorldJson.Boolean(a, "modifierAtStart"),
                };
                // Phase 7's draft flags exist from scheduleVersion 2 on; a version-1 file never has them.
                if (result.ScheduleVersion >= 2)
                {
                    act.TeammateAfter = Ints(a, "teammateAfter");
                    act.ShrineUpgradeAfter = Ints(a, "shrineUpgradeAfter");
                }
                // Phase 8's anomaly node and twist roll exist from scheduleVersion 3 on.
                if (v3)
                {
                    act.AnomalyAtStart = NpcWorldJson.Boolean(a, "anomalyAtStart");
                    if (a.TryGetValue("twist", out object tw) && tw is IDictionary<string, object> twist)
                    {
                        act.TwistPool = NpcWorldJson.Strings(twist, "pool") ?? new List<string>();
                        act.TwistChance = NpcWorldJson.Integer(twist, "chance", 0);
                    }
                }
                foreach (var slot in NpcWorldJson.List(a, "combat").Cast<object>().Select(NpcWorldJson.Object))
                    act.Combat.Add(new DungeonRunCombatSlot { Pool = NpcWorldJson.Text(slot, "pool"), Count = NpcWorldJson.Integer(slot, "count") });
                if (a.TryGetValue("draft", out object d) && d is IDictionary<string, object> draft)
                {
                    act.DraftOptions = NpcWorldJson.Integer(draft, "options", 3);
                    act.DraftTakes = NpcWorldJson.Integer(draft, "takes", 3);
                }
                if (a.TryGetValue("tavern", out object t) && t is IDictionary<string, object> tavern)
                {
                    act.TavernGold = NpcWorldJson.Integer(tavern, "gold", 0);
                    act.TavernOffers = NpcWorldJson.Integer(tavern, "offers", 0);
                }
                schedule.Acts.Add(act);
            }
            IDictionary<string, object> finaleRow = null;
            if (row.TryGetValue("finale", out object f) && f is IDictionary<string, object> finale)
            {
                schedule.FinaleEnabled = NpcWorldJson.Boolean(finale, "enabled");
                schedule.FinaleHeroRelay = NpcWorldJson.Boolean(finale, "heroRelay");
                schedule.FinaleBosses = NpcWorldJson.Strings(finale, "fixedBosses") ?? new List<string>();
                finaleRow = finale;
            }
            result.Schedules[pair.Key] = schedule;
            finales[schedule] = finaleRow;
        }
        foreach (var pair in sameActs)
        {
            var source = result.Find(pair.Value) ?? throw new InvalidDataException("schedule-v1.json: " + pair.Key.Id + " sameActsAs names unknown schedule " + pair.Value);
            // The source's own acts only: its finale act (if any) is synthesized below and is not shared.
            pair.Key.Acts.AddRange(source.Acts);
        }
        // Phase 8: an enabled finale is one synthesized last act (its bosses in order, one per floor, no card draft), so the
        // flattened nodes, the shape and every act accessor treat it like any act. A disabled finale stays data only, and
        // every older schedule (finale disabled) keeps its shape.
        foreach (var pair in finales.Where(p => v3 && p.Key.FinaleEnabled && p.Key.FinaleBosses.Count > 0))
        {
            var finale = pair.Value;
            int n = pair.Key.FinaleBosses.Count;
            int[] Curve(string key, int fill) { var v = Ints(finale, key); return v.Length == n ? v : Enumerable.Repeat(v.Length > 0 ? v[v.Length - 1] : fill, n).ToArray(); }
            var act = new DungeonRunAct
            {
                Id = NpcWorldJson.Text(finale, "id", false) ?? "F", Name = NpcWorldJson.Text(finale, "name", false) ?? "Finale",
                Floors = n, FixedBosses = new List<string>(pair.Key.FinaleBosses), MajorPool = DungeonRunEncounterData.FinalePool,
                BossHealth = Curve("bossHealth", 70), BossMana = Curve("bossMana", 0),
                TavernAtStart = NpcWorldJson.Boolean(finale, "tavernBefore"), HeroRelay = pair.Key.FinaleHeroRelay,
                AnomalyAtStart = NpcWorldJson.Boolean(finale, "anomalyAtStart"),
            };
            if (finale.TryGetValue("tavern", out object t) && t is IDictionary<string, object> tavern)
            {
                act.TavernGold = NpcWorldJson.Integer(tavern, "gold", 0);
                act.TavernOffers = NpcWorldJson.Integer(tavern, "offers", 0);
            }
            // Family 18: the finale's own twist (acts-v3h: DALA_830 The Finale, the rule the four fixed fights are), rolled at NewRun
            // like an act's twist.
            if (finale.TryGetValue("twist", out object ftw) && ftw is IDictionary<string, object> finaleTwist)
            {
                act.TwistPool = NpcWorldJson.Strings(finaleTwist, "pool") ?? new List<string>();
                act.TwistChance = NpcWorldJson.Integer(finaleTwist, "chance", 0);
            }
            pair.Key.Acts.Add(act);
        }
        foreach (var m in NpcWorldJson.List(root, "modifiers").Cast<object>().Select(NpcWorldJson.Object))
            result.Modifiers.Add(new DungeonRunModifier
            {
                Id = NpcWorldJson.Text(m, "id"), Name = NpcWorldJson.Text(m, "name"),
                BossHealthDelta = NpcWorldJson.Integer(m, "bossHealthDelta", 0),
                DraftOptionsDelta = NpcWorldJson.Integer(m, "draftOptionsDelta", 0),
                TavernGoldDelta = NpcWorldJson.Integer(m, "tavernGoldDelta", 0),
                BossManaDelta = NpcWorldJson.Integer(m, "bossManaDelta", 0),
                PlayerHealthDelta = NpcWorldJson.Integer(m, "playerHealthDelta", 0),
                OpeningHandBonus = NpcWorldJson.Integer(m, "openingHandBonus", 0),
                ExtraTreasureAfterMajor = NpcWorldJson.Boolean(m, "extraTreasureAfterMajor"),
                UnknownKnobs = m.Keys.Where(k => k != "id" && k != "name" && k != "text" && !ModifierKnobs.Contains(k)).OrderBy(k => k, StringComparer.Ordinal).ToList(),
            });
        return result;
    }

    private static int[] Ints(IDictionary<string, object> row, string key) =>
        row.TryGetValue(key, out object v) && v is IList list
            ? list.Cast<object>().Select(x => Convert.ToInt32(x, System.Globalization.CultureInfo.InvariantCulture)).ToArray()
            : new int[0];
}

// ---------------------------------------------------------------------- Bob's tavern (phase 5: tavern-v1.json)

/// <summary>
/// What one of Bob's deck enchantments does to a run card: the display and validation view only (the engine applies the
/// real enchantment, DungeonRunContent TavernEnchantments). <see cref="Target"/>: "minion" (stat buffs on a minion),
/// "weapon" (Attack and Durability on a weapon), "cost" (any card) or "marker" (no stats: the opening flag).
/// </summary>
internal sealed class DungeonRunEnchantment
{
    internal string Id, Target;
    internal int Attack, Health, CostDelta;
    /// <summary>Sets the cost to this value (DALA_903e: 0); null for a delta enchantment.</summary>
    internal int? SetCost;
}

/// <summary>One tavern option (tavern-v1.json "options"): the original tavern card id and the op it runs.</summary>
internal sealed class DungeonRunTavernOption
{
    internal string Id, Op, Target, Ench, Pool, Sample, AliasOf;
    internal int Cost, Weight, N, Amount;
    internal bool KeepMods, OncePerVisit;
}

/// <summary>tavern-v1.json: board sizes, Bob's minion cost cap per act, the options and the deferred tavern cards.</summary>
internal sealed class DungeonRunTavernTable
{
    internal int TavernVersion;
    internal int FriendlyBoard = 4, BobBoard = 4;
    internal int[] BobMaxCostByAct = new int[0];
    internal List<DungeonRunTavernOption> Options = new List<DungeonRunTavernOption>();
    /// <summary>Tavern cards kept out of the options, with the reason (ULDA_607 House Special).</summary>
    internal List<KeyValuePair<string, string>> Deferred = new List<KeyValuePair<string, string>>();

    /// <summary>The ops an option may run (DungeonRunTavernNode implements each).</summary>
    internal static readonly string[] KnownOps =
    {
        "recruit", "remove", "setcost", "health", "opening", "recruitAll", "discover", "buff", "removeAllFriendly", "copy",
        "removeFromSample", "reroll", "discountFromSample", "replace", "discoverOpening", "discoverBuff", "rerollTribe",
        "removeBuffNeighbours", "removeWhereCostAtMost",
    };
    /// <summary>The discover pools an option may name (computed at runtime from the catalog plus admission).</summary>
    internal static readonly string[] KnownPools = { "legendaryMinion", "minion", "spell", "anyClassWeapon" };
    /// <summary>The sample kinds an option may name ("spell": spells of the run deck).</summary>
    internal static readonly string[] KnownSamples = { "spell" };
    /// <summary>House Special: never an option (Bob's Bombastic Decks were server-side).</summary>
    internal const string HouseSpecial = "ULDA_607";

    /// <summary>The deck enchantments a run card may carry (DungeonRunCard.Mods): Bob's original tavern enchantments.</summary>
    internal static readonly IReadOnlyDictionary<string, DungeonRunEnchantment> KnownEnchantments = new[]
    {
        new DungeonRunEnchantment { Id = "DALA_903e", Target = "cost", SetCost = 0 },
        new DungeonRunEnchantment { Id = "DALA_905e", Target = "marker" },
        new DungeonRunEnchantment { Id = "DALA_906e", Target = "minion", Attack = 1, Health = 1 },
        new DungeonRunEnchantment { Id = "DALA_908e", Target = "minion", Attack = 2, Health = 2 },
        new DungeonRunEnchantment { Id = "DALA_913e", Target = "minion", Attack = 4, Health = 4, CostDelta = 2 },
        new DungeonRunEnchantment { Id = "DALA_914e", Target = "cost", CostDelta = -3 },
        new DungeonRunEnchantment { Id = "ULDA_603e", Target = "weapon", Attack = 2, Health = 2 },
        new DungeonRunEnchantment { Id = "ULDA_605e", Target = "cost", CostDelta = -1 },
        new DungeonRunEnchantment { Id = "ULDA_606e", Target = "minion", Attack = 2, Health = 2 },
    }.ToDictionary(e => e.Id, StringComparer.Ordinal);

    /// <summary>The opening-hand marker enchantment (Right Hand Man): attached to a flagged card at match start, never stored in its Mods.</summary>
    internal const string OpeningMarker = "DALA_905e";

    internal DungeonRunTavernOption Option(string id) => Options.FirstOrDefault(o => o.Id == id);

    internal static DungeonRunTavernTable Parse(string json)
    {
        var root = NpcWorldJson.Object(NpcWorldJson.Parse(json));
        var table = new DungeonRunTavernTable { TavernVersion = NpcWorldJson.Integer(root, "tavernVersion") };
        if (table.TavernVersion < 1) throw new InvalidDataException("tavern-v1.json: tavernVersion must be 1 or more");
        if (root.TryGetValue("board", out object b) && b is IDictionary<string, object> board)
        {
            table.FriendlyBoard = NpcWorldJson.Integer(board, "friendly", 4);
            table.BobBoard = NpcWorldJson.Integer(board, "bob", 4);
            table.BobMaxCostByAct = board.TryGetValue("bobMaxCostByAct", out object caps) && caps is IList list
                ? list.Cast<object>().Select(x => Convert.ToInt32(x, System.Globalization.CultureInfo.InvariantCulture)).ToArray() : new int[0];
        }
        foreach (var o in NpcWorldJson.List(root, "options").Cast<object>().Select(NpcWorldJson.Object))
            table.Options.Add(new DungeonRunTavernOption
            {
                Id = NpcWorldJson.Text(o, "id"), Op = NpcWorldJson.Text(o, "op"),
                Target = NpcWorldJson.Text(o, "target", false), Ench = NpcWorldJson.Text(o, "ench", false),
                Pool = NpcWorldJson.Text(o, "pool", false), Sample = NpcWorldJson.Text(o, "sample", false),
                AliasOf = NpcWorldJson.Text(o, "aliasOf", false),
                Cost = NpcWorldJson.Integer(o, "cost", 0), Weight = NpcWorldJson.Integer(o, "weight", 0),
                N = NpcWorldJson.Integer(o, "n", 0), Amount = NpcWorldJson.Integer(o, "amount", 0),
                KeepMods = NpcWorldJson.Boolean(o, "keepMods"), OncePerVisit = NpcWorldJson.Boolean(o, "oncePerVisit"),
            });
        if (root.TryGetValue("deferred", out object d) && d is IList deferred)
            foreach (var row in deferred.Cast<object>().Select(NpcWorldJson.Object))
                table.Deferred.Add(new KeyValuePair<string, string>(NpcWorldJson.Text(row, "id"), NpcWorldJson.Text(row, "reason")));
        return table;
    }
}

// ---------------------------------------------------------------------- imported encounters (phase 8: encounters-v1.json)
// Phase 8: the imported adventure encounters (data/dungeon-run/encounters-v1.json, generated by tools/dungeon-run-catalog from
// data/dungeon-run/reference/encounters/F<NN>.json). An encounter is a DungeonRunBoss row with a provenance other than
// "solostone": it is appended to DungeonRunData.Bosses after the twenty custom bosses (so their order and indexes never
// move), its decks go to DungeonRunData.BossDecks, and the fields below carry what makes it distinctive: its tier (which
// pools it is drawn from), forms, start block, shrine variants, fight-only hero cards, relay heroes and flags. Pure data:
// no engine or client types. It lives in this file because every project that compiles DungeonRunData.cs alone (both tools, the
// audit harnesses) must keep compiling: DungeonRunData.Parse reads the encounter file through it.

/// <summary>One boss form (encounters-v1.json "forms"): entered at a Health threshold, on death, or by a script.</summary>
internal sealed class DungeonRunForm
{
    /// <summary>The form's hero card (null: the hero entity stays) and power (null: the power stays).</summary>
    internal string Hero, Power;
    /// <summary>The form's deck id in DungeonRunData.BossDecks (null: the deck stays).</summary>
    internal string Deck;
    internal int Health, HealthAtMost, Draw;
    internal bool OnDeath, Script, KeepExcess;
}

/// <summary>An encounter's start block (encounters-v1.json "start"): card ids, one entry per copy. Match-only: it never touches a run deck record.</summary>
internal sealed class DungeonRunStart
{
    internal List<string> BossBoard = new List<string>(), PlayerBoard = new List<string>(), BossDeckAdd = new List<string>(),
        PlayerDeckAdd = new List<string>(), BossHandAdd = new List<string>(), PlayerHandAdd = new List<string>();
    internal string BossWeapon;
    internal int BossArmor, BossOpeningHandBonus;
    /// <summary>The boss's start Mana Crystals (replaces the act curve's bonus, still capped by bossManaCap); null keeps the curve.</summary>
    internal int? BossMana;
    internal IEnumerable<string> BossCards => BossBoard.Concat(BossDeckAdd).Concat(BossHandAdd).Concat(BossWeapon == null ? new string[0] : new[] { BossWeapon });
    internal IEnumerable<string> PlayerCards => PlayerBoard.Concat(PlayerDeckAdd).Concat(PlayerHandAdd);
}

/// <summary>A shrine variant of a Rumble Run champion (encounters-v1.json "variants"): the shrine on its board and the deck built around it.</summary>
internal sealed class DungeonRunVariant
{
    internal string Id, Shrine, Deck;
}

/// <summary>
/// A hero card the run player is given for this fight (encounters-v1.json "heroCards"; Hagatha's monster hunters): the card,
/// the cards that join the deck when it is played, the passive treasures its Battlecry offers, and the run hero cards it is not
/// given to (the run's own hunter).
/// </summary>
internal sealed class DungeonRunHeroCard
{
    internal string Hero;
    internal List<string> Deck = new List<string>(), Passives = new List<string>(), SkipFor = new List<string>();
}

/// <summary>A relay hero of a finale (encounters-v1.json "relay"; the Tombs explorers against Tekahn): portrait, power, Health and deck id.</summary>
internal sealed class DungeonRunRelayHero
{
    internal string Hero, Power, Deck;
    internal int Health;
    internal List<string> SkipFor = new List<string>();
}

/// <summary>One card substitution the encounter tool made in a deck (recorded as an adaptation).</summary>
internal sealed class DungeonRunSubstitution
{
    internal string Wiki, Listed, Used, Reason;
}

/// <summary>Where an encounter deck comes from: its kind, the page it was transcribed from, and what the tool changed.</summary>
internal sealed class DungeonRunDeckSource
{
    /// <summary>"authentic" (the listed cards, unchanged), "substituted" (same size, some cards replaced), "extended" (a short
    /// list or a pool filled to size) or "curated" (no usable list: built from scripted admitted cards).</summary>
    internal string Kind = KindAuthentic;
    internal string Url, Read, List;
    internal List<DungeonRunSubstitution> Substitutions = new List<DungeonRunSubstitution>();
    internal const string KindAuthentic = "authentic", KindSubstituted = "substituted", KindExtended = "extended", KindCurated = "curated";
    internal static readonly string[] Kinds = { KindAuthentic, KindSubstituted, KindExtended, KindCurated };
}

/// <summary>An encounter that is not imported (encounters-v1.json "rejected"): the ledger shows its reason and lift.</summary>
internal sealed class DungeonRunRejectedEncounter
{
    internal string Id, Name, Power, Reason, Lift;
    /// <summary>Card ids that are rejected with it (its tokens, its other forms).</summary>
    internal List<string> Cards = new List<string>();
}

/// <summary>The encounter file's parser and the encounter model's constants.</summary>
internal static class DungeonRunEncounterData
{
    internal const int SchemaVersion = 1;
    internal const string CustomProvenance = "solostone";
    /// <summary>The adventures an encounter may come from (DungeonRunBoss.Provenance).</summary>
    internal static readonly string[] Provenances = { "LOOT", "GIL", "TRL", "DALA", "ULDA" };
    /// <summary>The tiers a row may name: four combat tiers, three majors and the finale.</summary>
    internal static readonly string[] Tiers = { "1", "2", "3", "4", "major1", "major2", "major3", "finale" };
    internal const string FinaleTier = "finale", FinalePool = "finale";
    /// <summary>The closed flag vocabulary (rule incompatibility and tests read it).</summary>
    internal static readonly string[] Flags =
    {
        "passive", "bothPlayers", "hiddenZone", "secrets", "forms", "start", "position", "shrine", "persistentDamage", "heroSwitch", "relay",
        "deckReplace", "doubleBattlecry", "doubleDeathrattle", "recast", "forcedAttack", "heroImmune", "boardStart", "damageCap", "noLoss",
        "listedDeck",
    };
    internal const string PersistentDamage = "persistentDamage", HeroSwitch = "heroSwitch", Relay = "relay", FormsFlag = "forms", ShrineFlag = "shrine";
    /// <summary>
    /// Family 09: a combat-tier row whose deck is part of its mechanic keeps the listed count (<see cref="MinDeck"/> to
    /// <see cref="MaxDeck"/>) instead of 30 (Tad's ten minions, the Treasure Vault's unused deck).
    /// </summary>
    internal const string ListedDeck = "listedDeck";

    /// <summary>The row's decks hold exactly 30 cards: a combat tier without the flag <see cref="ListedDeck"/>.</summary>
    internal static bool ThirtyCardDeck(string tier, IEnumerable<string> flags) => IsCombatTier(tier) && (flags == null || !flags.Contains(ListedDeck));

    /// <summary>The pool an encounter tier is drawn from: "enc-t1".."enc-t4", "enc-major1".."enc-major3", "finale".</summary>
    internal static string PoolOf(string tier) =>
        tier == FinaleTier ? FinalePool : tier != null && tier.StartsWith("major", StringComparison.Ordinal) ? "enc-" + tier : "enc-t" + tier;

    /// <summary>A combat tier ("1".."4"): its decks hold exactly 30 cards. A major, a finale boss and a form deck keep their own count.</summary>
    internal static bool IsCombatTier(string tier) => tier == "1" || tier == "2" || tier == "3" || tier == "4";

    /// <summary>The deck sizes an encounter deck may have outside the combat tiers (majors, finale bosses, form decks).</summary>
    internal const int MinDeck = 10, MaxDeck = 60;

    private static IDictionary<string, object> Obj(object value) =>
        value as IDictionary<string, object> ?? throw new InvalidDataException("encounters-v1.json: expected a JSON object.");

    private static List<string> Ids(IDictionary<string, object> row, string key) => NpcWorldJson.Strings(row, key) ?? new List<string>();

    /// <summary>
    /// Appends the encounters of <paramref name="json"/> to <paramref name="data"/> (after the custom bosses) and their decks to
    /// its boss decks. A boss id or a deck id that already exists is a data error: an encounter never renames or replaces one.
    /// </summary>
    internal static void Parse(DungeonRunData data, string json)
    {
        var root = Obj(NpcWorldJson.Parse(json));
        if (NpcWorldJson.Integer(root, "schemaVersion") != SchemaVersion) throw new InvalidDataException("encounters-v1.json: unsupported schemaVersion");
        data.EncountersVersion = NpcWorldJson.Integer(root, "encountersVersion", 1);
        if (root.TryGetValue("decks", out object decks) && decks != null)
            foreach (var pair in Obj(decks))
            {
                if (data.BossDecks.ContainsKey(pair.Key)) throw new InvalidDataException("encounters-v1.json: deck " + pair.Key + " already exists");
                data.BossDecks[pair.Key] = ((IList)pair.Value).Cast<object>().Select(v => (string)v).ToList();
            }
        foreach (var row in NpcWorldJson.List(root, "encounters").Cast<object>().Select(Obj))
        {
            var boss = ParseRow(row);
            if (data.Bosses.Any(b => b.Id == boss.Id)) throw new InvalidDataException("encounters-v1.json: boss " + boss.Id + " already exists");
            data.Bosses.Add(boss);
        }
        if (root.TryGetValue("rejected", out object rejected) && rejected is IList rejectedRows)
            foreach (var row in rejectedRows.Cast<object>().Select(Obj))
                data.RejectedEncounters.Add(new DungeonRunRejectedEncounter
                {
                    Id = NpcWorldJson.Text(row, "id"), Name = NpcWorldJson.Text(row, "name", false), Power = NpcWorldJson.Text(row, "power", false),
                    Reason = NpcWorldJson.Text(row, "reason"), Lift = NpcWorldJson.Text(row, "lift", false), Cards = Ids(row, "cards"),
                });
    }

    private static DungeonRunDeckSource Source(IDictionary<string, object> deck)
    {
        var source = new DungeonRunDeckSource { Kind = NpcWorldJson.Text(deck, "kind", false) ?? DungeonRunDeckSource.KindAuthentic };
        if (deck.TryGetValue("source", out object s) && s is IDictionary<string, object> src)
        {
            source.Url = NpcWorldJson.Text(src, "url", false);
            source.Read = NpcWorldJson.Text(src, "read", false);
            source.List = NpcWorldJson.Text(src, "list", false);
        }
        if (deck.TryGetValue("substitutions", out object subs) && subs is IList list)
            foreach (var sub in list.Cast<object>().Select(Obj))
                source.Substitutions.Add(new DungeonRunSubstitution
                {
                    Wiki = NpcWorldJson.Text(sub, "wiki", false), Listed = NpcWorldJson.Text(sub, "listed", false),
                    Used = NpcWorldJson.Text(sub, "used", false), Reason = NpcWorldJson.Text(sub, "reason", false),
                });
        return source;
    }

    private static DungeonRunBoss ParseRow(IDictionary<string, object> row)
    {
        string tier = NpcWorldJson.Text(row, "tier");
        var deck = Obj(row["deck"]);
        int health = NpcWorldJson.Integer(row, "health", 0);
        int manaCap = NpcWorldJson.Integer(row, "bossManaCap", -1);
        var boss = new DungeonRunBoss
        {
            Id = NpcWorldJson.Text(row, "id"), Name = NpcWorldJson.Text(row, "name"),
            Provenance = NpcWorldJson.Text(row, "provenance"), Family = NpcWorldJson.Text(row, "family", false),
            HeroCard = NpcWorldJson.Text(row, "hero"), Power = NpcWorldJson.Text(row, "power"),
            Tier = tier, Pools = new List<string> { PoolOf(tier) },
            Health = health > 0 ? health : (int?)null, FixedHealth = NpcWorldJson.Boolean(row, "fixedHealth"),
            HealthOffset = NpcWorldJson.Integer(row, "healthOffset", 0),
            BossManaCap = manaCap >= 0 ? manaCap : (int?)null,
            Archetype = NpcWorldJson.Text(row, "archetype", false),
            Deck = NpcWorldJson.Text(deck, "id"), Source = Source(deck),
            Flags = Ids(row, "flags"), BossGeneratedSecrets = NpcWorldJson.Boolean(row, "bossGeneratedSecrets"),
            Cards = Ids(row, "cards"), IncompatibleRules = Ids(row, "incompatibleRules"),
            IncompatibleModifiers = Ids(row, "incompatibleModifiers"),
            Unlock = NpcWorldJson.Text(row, "unlock", false),
        };
        if (row.TryGetValue("level", out object level) && level is IDictionary<string, object> lv)
        {
            boss.LevelSource = NpcWorldJson.Text(lv, "source", false);
            boss.LevelOriginal = NpcWorldJson.Integer(lv, "original", 0);
        }
        if (row.TryGetValue("start", out object st) && st is IDictionary<string, object> start)
        {
            int mana = NpcWorldJson.Integer(start, "bossMana", -1);
            boss.Start = new DungeonRunStart
            {
                BossBoard = Ids(start, "bossBoard"), PlayerBoard = Ids(start, "playerBoard"), BossDeckAdd = Ids(start, "bossDeckAdd"),
                PlayerDeckAdd = Ids(start, "playerDeckAdd"), BossHandAdd = Ids(start, "bossHandAdd"), PlayerHandAdd = Ids(start, "playerHandAdd"),
                BossWeapon = NpcWorldJson.Text(start, "bossWeapon", false), BossArmor = NpcWorldJson.Integer(start, "bossArmor", 0),
                BossOpeningHandBonus = NpcWorldJson.Integer(start, "bossOpeningHandBonus", 0), BossMana = mana >= 0 ? mana : (int?)null,
            };
        }
        if (row.TryGetValue("forms", out object forms) && forms is IList formRows)
            foreach (var f in formRows.Cast<object>().Select(Obj))
            {
                var at = f.TryGetValue("at", out object a) && a is IDictionary<string, object> when ? when : new Dictionary<string, object>();
                boss.Forms.Add(new DungeonRunForm
                {
                    Hero = NpcWorldJson.Text(f, "hero", false), Power = NpcWorldJson.Text(f, "power", false),
                    Deck = f.TryGetValue("deck", out object fd) && fd is IDictionary<string, object> formDeck ? NpcWorldJson.Text(formDeck, "id") : null,
                    Health = NpcWorldJson.Integer(f, "health", 0), Draw = NpcWorldJson.Integer(f, "draw", 0),
                    HealthAtMost = NpcWorldJson.Integer(at, "healthAtMost", 0), OnDeath = NpcWorldJson.Boolean(at, "onDeath"),
                    Script = NpcWorldJson.Boolean(at, "script"), KeepExcess = NpcWorldJson.Boolean(f, "keepExcess"),
                });
            }
        if (row.TryGetValue("variants", out object variants) && variants is IList variantRows)
            foreach (var v in variantRows.Cast<object>().Select(Obj))
                boss.Variants.Add(new DungeonRunVariant
                {
                    Id = NpcWorldJson.Text(v, "id"), Shrine = NpcWorldJson.Text(v, "shrine", false),
                    Deck = NpcWorldJson.Text(Obj(v["deck"]), "id"),
                });
        if (row.TryGetValue("heroCards", out object heroCards) && heroCards is IList heroRows)
            foreach (var h in heroRows.Cast<object>().Select(Obj))
                boss.HeroCards.Add(new DungeonRunHeroCard
                {
                    Hero = NpcWorldJson.Text(h, "hero"), Deck = Ids(h, "deck"), Passives = Ids(h, "passives"), SkipFor = Ids(h, "skipFor"),
                });
        if (row.TryGetValue("relay", out object relay) && relay is IList relayRows)
            foreach (var h in relayRows.Cast<object>().Select(Obj))
                boss.Relay.Add(new DungeonRunRelayHero
                {
                    Hero = NpcWorldJson.Text(h, "hero"), Power = NpcWorldJson.Text(h, "power"), Deck = NpcWorldJson.Text(h, "deck"),
                    Health = NpcWorldJson.Integer(h, "health", 0), SkipFor = Ids(h, "skipFor"),
                });
        return boss;
    }
}
